using DevExpress.AspNetCore; // AddDevExpressControls — Report Designer wiring
using DevExpress.AspNetCore.Reporting; // ConfigureReportingServices (StartupExtensions) — confirmed via ikdasm against the restored 26.1.3 package
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using System.Security.Claims;
using Microsoft.OpenApi.Models;
using Serilog;
using Serilog.Events;
using Serilog.Sinks.MSSqlServer;
using SolutionOne_BusinessLogicLayer.Middleware.Common;
using SolutionOne_BusinessLogicLayer.Middleware.Common.StartupTasks;
using SolutionOne_BusinessLogicLayer.Middleware.HR;
using SolutionOne_BusinessLogicLayer.Middleware.Canteen_Management;
using SolutionOne_BusinessLogicLayer.Middleware.HR_Training;
using SolutionOne_BusinessLogicLayer.Middleware.Travel_Management;
using SolutionOne_BusinessLogicLayer.Services.Mail_Config.Implementation;
// using SolutionOne_BusinessLogicLayer.Services.Push.Implementation; // disabled: guard push notification feature, not active yet
// using SolutionOne_BusinessLogicLayer.Services.Push.Interface;
using SolutionOne_BusinessLogicLayer.Middleware.VMS;
using SolutionOne_BusinessLogicLayer.Middleware.IncomeTax;
using SolutionOne_BusinessLogicLayer.Middleware.Payroll;
using SolutionOne_BusinessLogicLayer.Middleware.AssetsManagement;
using SolutionOne_BusinessLogicLayer.Middleware.Dashboard;
using SolutionOne_BusinessLogicLayer.Middleware.Report;
using SolutionOne_BusinessLogicLayer.Middleware.ReportDesigner;
using SolutionOne_BusinessLogicLayer.Middleware.Approval;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.CommonModels.MailConfig;
using SolutionOne_Core.PMSModels;
using SolutionOne_Core.Utilities;
using SolutionOne_Core.HRModels.OpenAi;
using SolutionOne_Core.HRModels.ResumeParsing;
using SolutionOne_BusinessLogicLayer.Services.HR.Interface;
using SolutionOne_BusinessLogicLayer.Services.HR.Implementation;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_BusinessLogicLayer.Services.Common.Implementation;
using SolutionOne_BusinessLogicLayer.Services.ReportDesigner.Implementation;
using SolutionOne_Core.TravelManagementModels.TravelSecurity;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Middleware.Common;
using SolutionOne_DataAccessLayer.Middleware.HR;
using SolutionOne_DataAccessLayer.Middleware.Canteen_Management;
using SolutionOne_DataAccessLayer.Middleware.HR_Training;
using SolutionOne_DataAccessLayer.Middleware.Travel_Management;
using SolutionOne_DataAccessLayer.Middleware.VMS;
using SolutionOne_DataAccessLayer.Middleware.IncomeTax;
using SolutionOne_DataAccessLayer.Middleware.Payroll;
using SolutionOne_DataAccessLayer.Middleware.AssetsManagement;
using SolutionOne_DataAccessLayer.Middleware.Dashboard;
using SolutionOne_DataAccessLayer.Middleware.Report;
using SolutionOne_DataAccessLayer.Middleware.ReportDesigner;
using SolutionOne_DataAccessLayer.Middleware.Approval;
using SolutionOneWebPortal_API.ControllerDecorators;
using SolutionOneWebPortal_API.Debugging;
using SolutionOneWebPortal_API.Exceptions;
using System.Text;

// Must run before anything else touches DevExpress reporting: ScriptPermissionManager.GlobalInstance
// only takes effect the FIRST time it's set (its setter is a no-op once already assigned), and
// defaults to Deny otherwise. Some legacy hr_payroll reports were authored with real embedded
// scripts (compiled event-handler code, not just SQL) in the full desktop Report Designer - without
// this, previewing them throws ScriptExecutionException. Explicit, deliberate tradeoff: Unrestricted
// mode lets any report's embedded script run arbitrary server-side code, acceptable here because
// only trusted internal admins can author/save reports through this designer.
DevExpress.XtraReports.Security.ScriptPermissionManager.GlobalInstance =
    new DevExpress.XtraReports.Security.ScriptPermissionManager(DevExpress.XtraReports.Security.ExecutionMode.Unrestricted);

var builder = WebApplication.CreateBuilder(args);

var debugMode = DebugModeOptions.Resolve(args);

// ✅ Register email senders before Build. IEmailService itself resolves to EmailServiceResolver
// (registered in CommonDependencyInjection.AddCommonServices), which picks ZeptoEmailService,
// SmtpEmailService or GraphEmailService (Microsoft Graph, HTTPS) per call based on the active EmailProviderSetting - so the concrete senders
// are registered here but nothing depends on them directly except the resolver.
// Zepto sends via the ZeptoMail HTTPS API (port 443), not SMTP, so it isn't affected by
// DigitalOcean's outbound SMTP port block; Smtp is for client deployments that run their own mail
// server instead of buying/verifying a domain for ZeptoMail.
builder.Services.Configure<ZeptoMailSettings>(builder.Configuration.GetSection(ZeptoMailSettings.SectionName));
builder.Services.Configure<SmtpSettings>(builder.Configuration.GetSection(SmtpSettings.SectionName));
// Password encryption must stay byte-for-byte compatible with the sibling hr_payroll project -
// both read/write HR_UserMaster.PasswordHash in the same database.
builder.Services.Configure<PasswordEncryptionSettings>(builder.Configuration.GetSection(PasswordEncryptionSettings.SectionName));
// TestSmtpConnection opens a real socket to a user-supplied host:port - without a limit here it
// doubles as a free port scanner for whoever is logged in. 5 attempts/minute per logged-in user
// (falls back to per-IP if unauthenticated) is generous for a settings page a person is manually
// testing, but blocks it being hammered as a scanning primitive.
builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.AddPolicy("smtp-test", httpContext =>
    {
        var partitionKey = httpContext.User.FindFirst("UserEmpId")?.Value
            ?? httpContext.Connection.RemoteIpAddress?.ToString()
            ?? "unknown";
        return System.Threading.RateLimiting.RateLimitPartition.GetFixedWindowLimiter(partitionKey, _ => new System.Threading.RateLimiting.FixedWindowRateLimiterOptions
        {
            PermitLimit = 5,
            Window = TimeSpan.FromMinutes(1),
            QueueLimit = 0
        });
    });
});
builder.Services.AddHttpClient<ZeptoEmailService>();
builder.Services.AddHttpClient<GraphEmailService>();
builder.Services.AddHttpClient();
// builder.Services.AddScoped<IPushNotificationService, PushNotificationService>(); // disabled: guard push notification feature, not active yet

// Add services to the container.
builder.Services.AddControllers(options =>
{
    options.Filters.Add<DynamicScreenFilter>();
    options.Filters.Add<DropdownOverrideFilter>();
    options.Filters.AddService<DebugActionArgumentsFilter>();
}).AddJsonOptions(options =>
{
    options.JsonSerializerOptions.ReferenceHandler = System.Text.Json.Serialization.ReferenceHandler.IgnoreCycles;
    options.JsonSerializerOptions.DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull;

    // Accept a DateOnly sent as a full timestamp, which is what every date box in the front end
    // produces (a JavaScript Date serialises as "2026-04-01T00:00:00.000Z"). Without these, any
    // model with a DateOnly property fails to bind the moment a user picks a date, and the screen
    // shows a raw .NET type name instead of saving. See DateOnlyJsonConverter.
    options.JsonSerializerOptions.Converters.Add(new SolutionOne_Core.Utilities.DateOnlyJsonConverter());
    options.JsonSerializerOptions.Converters.Add(new SolutionOne_Core.Utilities.NullableDateOnlyJsonConverter());
});
builder.Services.AddScoped<DynamicScreenFilter>();
builder.Services.AddScoped<DropdownOverrideFilter>();

// Was defined but never actually registered - UseExceptionHandler(_ => {}) below is a different,
// unrelated overload (builds a manual fallback pipeline) and does not pick up an IExceptionHandler
// from DI. AddExceptionHandler + AddProblemDetails is what makes GlobalExceptionHandler run.
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();
builder.Services.AddProblemDetails();
// Adding debug mode options.
// TODO 06-08-2026: Imrove upon this
builder.Services.AddSingleton<DebugModeOptions>(debugMode);

//builder.Services.AddDbContext<HrContext>(options => options.UseSqlServer(builder.Configuration.GetConnectionString("WebPortalConnectionString")));

