var aesEncryption = builder.Services.BuildServiceProvider().GetService<AESEncryption>();
if (aesEncryption != null)
{
    string? encryptedConnectionString = builder.Configuration.GetConnectionString("WebPortalConnectionString");

    if (!string.IsNullOrEmpty(encryptedConnectionString))
    {
        /// Decrypt the connection string
        string? decryptedConnectionString = aesEncryption.Decrypt(encryptedConnectionString, "Gsspl@2024Gsspl@");

        builder.Services.AddSingleton(new DbConnectionConfig
        {
            ConnectionString = decryptedConnectionString
        });

        if (!string.IsNullOrEmpty(decryptedConnectionString))
        {
            /// Configure DbContext with decrypted connection string
            builder.Services.AddDbContext<HrmsystemContext>(options =>
            {
                options.UseSqlServer(decryptedConnectionString, x => x.UseCompatibilityLevel(120));

                // --debug / HRMS_DEBUG_MODE=true: log every generated SQL statement and its bound
                // parameter VALUES (EnableSensitiveDataLogging) through Serilog's Debug sink, so the
                // repository -> DB boundary is visible alongside the request/response and action-args
                // logs below. Never leave this on outside local debugging - it logs real column values.
                if (debugMode.Enabled)
                {
                    options.EnableSensitiveDataLogging()
                        .LogTo(msg => Serilog.Log.Debug("EFCore: {Msg}", msg), Microsoft.Extensions.Logging.LogLevel.Information);
                }
            });

            ///=============Added Serilog By Jayshree on 21-07-2025
            Log.Logger = new LoggerConfiguration()
                .Enrich.FromLogContext() /// Automatically capture contextual information
				.MinimumLevel.Debug() /// Set the minimum log level to Debug
				.MinimumLevel.Override("Microsoft", LogEventLevel.Warning) /// Override minimum log level for Microsoft namespace
				.WriteTo.Console() /// Write log events to the console
                .WriteTo.MSSqlServer(
                                connectionString: decryptedConnectionString,
                                sinkOptions: new MSSqlServerSinkOptions
                                {
                                    TableName = "WebApiLogs",
                                    AutoCreateSqlTable = false /// Automatically create the SQL table if it doesn't exist
                	},
                                columnOptions: new ColumnOptions(), /// Customize column options as needed
                	restrictedToMinimumLevel: LogEventLevel.Error) /// Set the minimum log level for the MSSqlServer sink
                .WriteTo.Conditional(
                    _ => debugMode.Enabled,
                    wt => wt.File(
                        $"logs/debug/{Environment.UserName}.log",
                        restrictedToMinimumLevel: LogEventLevel.Debug,
                        rollingInterval: RollingInterval.Day,
                        outputTemplate: "{Timestamp:HH:mm:ss.fff} [{Level:u3}] {Message:lj}{NewLine}{Exception}"
                    )
                )
                .CreateLogger();

            ///=============Added Serilog By Jayshree on 21-07-2025 Configure the host to use Serilog for logging
            builder.Host.UseSerilog();
        }

