using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using SolutionOne_Core.CommonModels;
using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
using SolutionOne_DataAccessLayer.Repositories.UDR.Interface;
using System.Data;
using System.Threading.Tasks;

namespace SolutionOne_DataAccessLayer.Repositories.Common.Implementation
{
	public class DbConnectionFactory(
		IDataSourceRepository repository,
		AESEncryption aes,
		IConfiguration configuration,
		IDapperContext defaultContext) : IDbConnectionFactory
	{
		private readonly IDataSourceRepository _repository = repository;
		private readonly AESEncryption _aes = aes;
		private readonly IConfiguration _configuration = configuration;
		private readonly IDapperContext _defaultContext = defaultContext;
		private const string ENCRYPTION_KEY = "Gsspl@2024Gsspl@";

		public async Task<IDbConnection> GetConnectionAsync(long? dataSourceId = null)
		{
			if (dataSourceId == null || dataSourceId <= 0)
			{
				return _defaultContext.Connection;
			}

			var ds = await _repository.GetDataSourceById(dataSourceId.Value);
			if (ds == null)
			{
				return _defaultContext.Connection;
			}

			string server = _aes.Decrypt(ds.ServerName, ENCRYPTION_KEY) ?? ds.ServerName;
			string db = _aes.Decrypt(ds.DatabaseName, ENCRYPTION_KEY) ?? ds.DatabaseName;
			string user = _aes.Decrypt(ds.Username, ENCRYPTION_KEY) ?? ds.Username;
			string pass = _aes.Decrypt(ds.Password, ENCRYPTION_KEY) ?? ds.Password;

			var builder = new SqlConnectionStringBuilder
			{
				DataSource = server,
				InitialCatalog = db,
				UserID = user,
				Password = pass,
				TrustServerCertificate = true,
				MultipleActiveResultSets = true,
				ConnectTimeout = 30
			};

			var conn = new SqlConnection(builder.ConnectionString);
			if (conn.State != ConnectionState.Open)
			{
				await conn.OpenAsync();
			}
			return conn;
		}
	}
}
