using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using SolutionOne_Core.CommonModels;
using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
using System.Data;

namespace SolutionOne_DataAccessLayer.Repositories.Common.Implementation
{
	public class DapperContext : IDapperContext
	{
		private readonly IConfiguration _configuration;
		private readonly string _connectionString;

		public IDbConnection Connection { get; private set; }
		public IDbTransaction? Transaction { get; private set; }

		public DapperContext(IConfiguration configuration)
		{
			_configuration = configuration;
			_connectionString = _configuration.GetConnectionString("WebPortalConnectionString");
			AESEncryption aes = new AESEncryption(_configuration);
			var key = "Gsspl@2024Gsspl@";
			var decrypt = aes.Decrypt(_connectionString, key);

			if (decrypt != null && !decrypt.Contains("MultipleActiveResultSets=True", StringComparison.OrdinalIgnoreCase))
			{
				decrypt = decrypt.TrimEnd(';') + ";MultipleActiveResultSets=True;";
			}

			Connection = new SqlConnection(decrypt);
		}

		public async Task BeginTransactionAsync()
		{
			if (Connection.State != ConnectionState.Open)
				Connection.Open();

			Transaction = Connection.BeginTransaction();
			await Task.CompletedTask;
		}

		public async Task CommitAsync()
		{
			Transaction?.Commit();
			Transaction?.Dispose();
			Transaction = null;
			if (Connection.State == ConnectionState.Open)
				Connection.Close();
			await Task.CompletedTask;
		}

		public async Task RollbackAsync()
		{
			Transaction?.Rollback();
			Transaction?.Dispose();
			Transaction = null;
			if (Connection.State == ConnectionState.Open)
				Connection.Close();
			await Task.CompletedTask;
		}

		public void Dispose()
		{
			if (Transaction != null)
			{
				Transaction.Dispose();
				Transaction = null;
			}
			if (Connection.State == ConnectionState.Open)
				Connection.Close();
			Connection?.Dispose();
		}
	}
}

