// Learn more about configuring Swagger/OpenAPI at https://aka.ms/aspnetcore/swashbuckle
builder.Services.AddEndpointsApiExplorer();
///============= Start: Added By Jayshree on 25-07-2025 for Configure CORS (Cross-Origin Resource Sharing) for the ASP.NET Core application
builder.Services.AddResponseCompression(o =>
{
    o.EnableForHttps = true;
    o.Providers.Add<Microsoft.AspNetCore.ResponseCompression.BrotliCompressionProvider>();
    o.Providers.Add<Microsoft.AspNetCore.ResponseCompression.GzipCompressionProvider>();
});
builder.Services.Configure<Microsoft.AspNetCore.ResponseCompression.BrotliCompressionProviderOptions>(o => o.Level = System.IO.Compression.CompressionLevel.Fastest);

builder.Services.AddCors(options =>
{
    // Define a CORS policy named "MyCorsPolicy"
    options.AddPolicy("MyCorsPolicy",
        builder =>
        {
            // Allow requests from any origin
            builder.AllowAnyOrigin()
                   // Allow any header in the requests
                   .AllowAnyHeader()
                   // Allow any HTTP method in the requests
                   .AllowAnyMethod();
        });
});

///=============Start: Added By Jayshree on 21-07-2025 for JWT Authorization
builder.Services.AddSwaggerGen(opt =>
{
    opt.SwaggerDoc("v1", new OpenApiInfo { Title = "Web Portal API", Version = "v1" });
    // HR and Payroll each define their own model with the same simple name (e.g.
    // AddAttendanceCycleConfigModel in both SolutionOne_Core.HRModels and .PayrollModels) -
    // Swashbuckle's default schemaId is just the simple name, so it collides across namespaces.
    // Using the full name keeps every type's schema distinct.
    opt.CustomSchemaIds(type => type.FullName?.Replace("+", "."));
    opt.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        In = ParameterLocation.Header,
        Description = "You need token for this",
        Name = "Authorization",
        Type = SecuritySchemeType.Http,
        BearerFormat = "JWT",
        Scheme = "bearer"
    });

    opt.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference
                {
                    Type=ReferenceType.SecurityScheme,
                    Id="Bearer"
                }
            },
            new string[]{}
        }
    });

});


var jwtConfig = builder.Configuration.GetSection("Jwt");
var jwtKey = jwtConfig["Key"] ?? throw new InvalidOperationException("Jwt:Key is missing from configuration.");

builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = "JwtScheme";
    options.DefaultChallengeScheme = "JwtScheme";
})
.AddJwtBearer("JwtScheme", options =>
{
    options.RequireHttpsMetadata = false;
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = true,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
        ValidIssuer = jwtConfig["Issuer"],
        ValidAudience = jwtConfig["Audience"],
        IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),
        ClockSkew = TimeSpan.FromMinutes(5),
        NameClaimType = ClaimTypes.Name,
        RoleClaimType = ClaimTypes.Role,
    };
});

builder.Services.AddAuthorization(options =>
{
    options.DefaultPolicy = new AuthorizationPolicyBuilder("JwtScheme")
        .RequireAuthenticatedUser()
        .Build();
});
///=============End: Added By Jayshree on 21-07-2025 for JWT Authorization
///


///=============Added Middleware By Jayshree on 21-07-2025 for Dependency Injection From MIDAS_DataAccessLayer.Middleware
builder.Services.AddCommonRepository();

///======== Register all Travel Management module repositories add by Urvi Joshi on 27-11-2025
builder.Services.AddTMRepository();

builder.Services.AddHrRepository();
builder.Services.AddHRTMRepository();
builder.Services.AddCmsRepository();

///======== Payroll module repositories — functionality ported from SolutionOneWeb, 14-08-2026

