import { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { catchError } from 'rxjs/operators';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { throwError } from 'rxjs';
import { ToastService } from './toaster.service';
import { AuthService } from './auth.service';
import { SILENT_REQUEST } from './loading-interceptor';

function resolveApiErrorMessage(error: HttpErrorResponse): string {
  const body = error.error as Record<string, unknown> | null | undefined;
  if (!body) {
    return error.message || 'Something went wrong. Please try again.';
  }

  const directMessage = body['message'] ?? body['Message'];
  if (typeof directMessage === 'string' && directMessage.trim()) {
    return directMessage.trim();
  }

  const validationErrors = body['errors'] ?? body['Errors'];
  if (validationErrors && typeof validationErrors === 'object') {
    const messages = Object.values(validationErrors as Record<string, unknown>)
      .flatMap((value) => (Array.isArray(value) ? value : [value]))
      .filter((value): value is string => typeof value === 'string' && value.trim().length > 0);
    if (messages.length) {
      return messages[0];
    }
  }

  const title = body['title'] ?? body['Title'];
  if (typeof title === 'string' && title.trim()) {
    return title.trim();
  }

  return error.message || 'Something went wrong. Please try again.';
}

export const customInterceptor: HttpInterceptorFn = (req, next) => {
  const router = inject(Router);
  const toast = inject<ToastService>(ToastService);
  const auth = inject(AuthService);

  if (req.url.includes('/LoginAuthentication') || req.url.includes('/validate') || req.url.includes('/ValidateGuestToken')) {
    return next(req);
  }

  const token = auth.getToken();
  const isGuestRoute =
    router.url.includes('/vms/guest-upload') ||
    router.url.includes('/vms/visitor-status') ||
    router.url.includes('/vms/self-register');
  const authRequest = token
    ? req.clone({
        setHeaders: {
          Authorization: `Bearer ${token}`,
        },
      })
    : req;

  return next(authRequest).pipe(
    catchError((error: HttpErrorResponse) => {
      const apiMessage = resolveApiErrorMessage(error);
      const isCanteenListGet =
        req.method === 'GET' &&
        /\/api\/(MealSession\/GetAllMealSessions|MenuPlan\/GetAllMenuPlans|ItemMaster\/GetAllItems|MenuPublish\/GetAllMenuPublishes)/i.test(req.url);
      // Session expiry is always surfaced (it affects every request, silent or not) — only the
      // generic failure-toast branches below are skippable per request, for a caller that already
      // shows its own inline "unavailable" UI instead (e.g. Travel Payment's SAP-backed bank calls).
      const silent = req.context.get(SILENT_REQUEST);

      if (error.status === 401 && !router.url.includes('/login')) {
        if (isGuestRoute) {
          toast.error(apiMessage || 'Your upload session has expired. Please use the link from your email again.');
        } else if (token) {
          auth.clearSession();
          router.navigate(['/login']);
          toast.error('Session expired. Please log in again.');
        } else {
          toast.error('Please log in to continue.');

