///// <param name="Password">The password of the user attempting to log in.</param>
///// Date: 21-07-2025
///// Developer: Jayshree Patel
[HttpPost]
[Route("LoginAuthentication")]
public async Task<IActionResult> Login([FromBody] UserLoginRequest loginRequest)
{
    // Initialize a response model
    ResponseModel responseModel = new ResponseModel();

    try
    {
        // Check if username or password is empty or null
        if (string.IsNullOrEmpty(loginRequest.UserName) || string.IsNullOrEmpty(loginRequest.PasswordHash))
        {
            // Log the error message to the database using Serilog
            _logger.LogError("Error: Username or password not provided.");

            // Prepare a bad request response
            responseModel.IsSuccess = false;
            responseModel.Status = HttpStatusCode.BadRequest;
            responseModel.Message = "Username or password not provided.";
            return BadRequest(responseModel);
        }

        // Attempt to login using the provided username and password
        var (response, data, permissions, menus) = await _service.Login(loginRequest.UserName, loginRequest.PasswordHash);
        if (!response.IsSuccess || data == null)
        {
            return Unauthorized(response);
        }

        // Call GenerateToken method and return the token
        string token = await GenerateTokenAsync(data);

        HttpContext.Session.SetInt32("UserId", (int)data.UserMasterId);
        HttpContext.Session.SetString("UserName", data.UserName);
        HttpContext.Session.SetString("UserRole", data.Role ?? ""); // Please handle null exceptions in a much better way
        HttpContext.Session.SetInt32("UserEmpId", (int)(data.EmployeeMasterId ?? 0));
        HttpContext.Session.SetString("CompanyId", data.CompanyMasterId.ToString() ?? "-1");

        // Get Roles
        var roles = await _permissionResolver.GetUserRolesAsync((int)data.UserMasterId);

        // Embed the user data and token directly in the response model's data
        response.Data = new
        {
            UserId = data.UserMasterId,
            userName = data.UserName,
            //Role = data.Role, // Legacy
            Roles = roles, // New RBAC System
                           //RoleId = data.Permission ?? 0,
            CompanyId = data.CompanyMasterId,
            BranchId = data.BranchId,
            EmployeeId = data.EmployeeMasterId,
            token,
            permissions = permissions, // Send permissions in JSON body, not JWT payload
            menus = menus // Send menus that the user has access to!
        };

        return Ok(response);
    }
    catch (Exception ex)
    {
        // Log the error message to the database using Serilog
        _logger.LogError("An error occurred: {ErrorMessage}", ex.Message);

        // Prepare an internal server error response
        responseModel.IsSuccess = false;
        responseModel.Status = HttpStatusCode.InternalServerError;
        responseModel.Message = "An error occurred while processing your request.";
        return StatusCode((int)HttpStatusCode.InternalServerError, responseModel);
    }
}
#endregion

