    public static string GetConnectionString()
    {
        // Re-read Web.config on every call so Initial Catalog changes apply
        // on the next page request without waiting for a full IIS recycle.
        ConfigurationManager.RefreshSection("connectionStrings");
        ConfigurationManager.RefreshSection("appSettings");

        if (!IsMultiTenantEnabled())
            return GetLegacyConnectionString();

        TenantClientInfo client = GetCurrentClient();
        if (client == null)
            return GetLegacyConnectionString();

        return BuildClientConnectionString(client);
    }

    /// <summary>
    /// Same resolution as GetConnectionString(), but never reads or writes
    /// Session - only HttpRuntime.Cache (via ResolveClientByHost) and the
    /// request URL. Session-state store providers must use this instead:
    /// Session itself is not yet backed by real storage while the provider
    /// is being asked which database to use for it.
