        return client != null ? BuildClientConnectionString(client) : GetLegacyConnectionString();
    }

    /// <summary>
    /// Active Initial Catalog from on-disk Web.config sqlConnectionString.
    /// </summary>
    public static string GetDatabaseName()
    {
        // Mirror GetConnectionString() so the reported database always matches the
        // one actually used for this request: the port-resolved client database
        // when multi-tenant resolves a client, otherwise the legacy
        // sqlConnectionString. (Previously this returned the legacy catalog first,
        // which reported HR_SolOne for every port even when a different client
        // database was in use.)
        try
