    /// - EmployeeStatutoryPack = Auto and Initial Catalog is HR / HR-UGANDA.
    /// </summary>
    public static bool IsHrRegionalClient()
    {
        string pack = ReadAppSettingFromWebConfigFile("EmployeeStatutoryPack");
        if (string.IsNullOrWhiteSpace(pack))
