            pack = ConfigurationManager.AppSettings["EmployeeStatutoryPack"] ?? "Auto";
        }

        pack = pack.Trim();
        if (string.Equals(pack, "India", StringComparison.OrdinalIgnoreCase))
            return false;

        if (string.Equals(pack, "Africa", StringComparison.OrdinalIgnoreCase)
            || string.Equals(pack, "HR", StringComparison.OrdinalIgnoreCase))
            return true;

