public static TenantClientInfo GetCurrentClient()
{
    // When multi-tenant mode is off, never touch the registry database
    // (masterConnectionString -> HR_Master). Callers treat null as
    // "use the legacy sqlConnectionString", so returning early here keeps
    // single-tenant requests from ever opening HR_Master - which the app
    // pool identity (e.g. IIS APPPOOL\HR) has no rights to, causing
    // "Cannot open database 'HR_Master' requested by the login".
    if (!IsMultiTenantEnabled())
        return null;

    HttpContext context = HttpContext.Current;
    if (context == null)
        return null;

    IList<string> hostKeys = GetRequestHostKeys(context);
    if (hostKeys.Count == 0)
        return null;

