    private static string ReadAppSettingFromWebConfigFile(string key)
    {
        try
        {
            string path = ResolveWebConfigPath();
            if (string.IsNullOrEmpty(path) || !File.Exists(path))
                return null;

            var doc = new XmlDocument();
            doc.Load(path);

            XmlNode node = doc.SelectSingleNode("//appSettings/add[@key='" + key + "']/@value");
            return node == null ? null : node.Value;
        }
        catch
        {
            return null;
        }
    }

    private static string ResolveWebConfigPath()
    {
        if (HttpContext.Current != null && HttpContext.Current.Server != null)
            return HttpContext.Current.Server.MapPath("~/Web.config");

        if (!string.IsNullOrEmpty(HttpRuntime.AppDomainAppPath))
            return Path.Combine(HttpRuntime.AppDomainAppPath, "Web.config");

        return null;
    }

    private static string GetRequiredConnectionString(string name)
    {
        string value = GetConnectionStringOrNull(name);
        if (string.IsNullOrWhiteSpace(value))
            throw new ConfigurationErrorsException("Missing connection string: " + name);

        return value;
    }

    private static string GetConnectionStringOrNull(string name)
    {
        ConnectionStringSettings settings = ConfigurationManager.ConnectionStrings[name];
        return settings == null ? null : settings.ConnectionString;
    }
}

[Serializable]
public class TenantClientInfo
{
    public int ClientID { get; set; }
    public string ClientCode { get; set; }
    public string HostName { get; set; }
    public string DatabaseName { get; set; }
    public string ConnectionString { get; set; }

    public static TenantClientInfo FromLegacy(string connectionString)
    {
        var builder = new SqlConnectionStringBuilder(connectionString);
        return new TenantClientInfo
        {
            ClientID = 0,
            ClientCode = "Legacy",
            HostName = string.Empty,
            DatabaseName = builder.InitialCatalog,
            ConnectionString = connectionString
        };
    }
}

