      is hidden from the customer - they see only the read-only "Validation Message" it
      produces. There is deliberately NO appSetting for it: the switch is a database row
      (dbo.HR_AppSetting 'SalaryHeadValidationSetup', migration 152) flipped on the
      Payroll/ModuleHide.aspx screen, because editing Web.config recycles the app pool and
      signs every logged-in user out. See App_Code/AppSettingStore.cs.
    -->
    <!--
      EnableMultiTenant - master switch for how the active database is chosen.

        true  = MULTI-CLIENT / MULTI-DATABASE.
                Each IIS port (host:port) is resolved to its own client database
                via masterConnectionString -> dbo.HR_ClientRegistry. Requires
                HR_Master + HR_ClientRegistry to be populated. If a request's
                host:port is not found in the registry it falls back to
                sqlConnectionString below.

        false = SINGLE DATABASE.
                Multi-tenant lookup is disabled completely; every request,
                session and migration uses the one sqlConnectionString below,
                regardless of port.
    -->
    <add key="EnableMultiTenant" value="false" />
    <!-- Employee page fields: Auto | India | Africa -->
    <add key="EmployeeStatutoryPack" value="Auto" />
    <!--
      Recruitment Portal (the separate Angular HRMS) SSO landing page. The left panel item
      Recruitment > Recruitment Portal redirects here with ?userId=&userRole=, and the portal
      logs the user straight in.
      To test against a local HRMS instead, change the value to
      http://localhost:4200/validate and start SolutionOneWebPortal_API on port 5043
