    private static void EnsureHistoryTable(SqlConnection conn)
    {
        using (var cmd = new SqlCommand(@"
            IF NOT EXISTS (
                SELECT 1 FROM sys.tables
                WHERE name = N'HR_SchemaMigrationHistory'
                  AND schema_id = SCHEMA_ID(N'dbo')
            )
            BEGIN
                CREATE TABLE dbo.HR_SchemaMigrationHistory (
                    MigrationID NVARCHAR(100) NOT NULL,
                    ScriptName  NVARCHAR(300) NOT NULL,
                    AppliedOn   DATETIME      NOT NULL CONSTRAINT DF_HR_SchemaMigrationHistory_AppliedOn DEFAULT (GETDATE()),
                    AppliedBy   NVARCHAR(100) NULL,
                    Checksum    NVARCHAR(100) NULL,
                    CONSTRAINT PK_HR_SchemaMigrationHistory PRIMARY KEY CLUSTERED (MigrationID)
                );
            END", conn))
        {
            cmd.CommandTimeout = GetCommandTimeoutSeconds();
            cmd.ExecuteNonQuery();
        }
    }

    private static HashSet<string> LoadAppliedMigrations(SqlConnection conn)
    {
        var applied = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        using (var cmd = new SqlCommand("SELECT MigrationID FROM dbo.HR_SchemaMigrationHistory", conn))
        using (SqlDataReader reader = cmd.ExecuteReader())
        {
            while (reader.Read())
                applied.Add(Convert.ToString(reader["MigrationID"]));
        }

        return applied;
    }

