            // Create claims, including the role
            var roleId = user.RoleId ?? 0;
            var branchId = user.BranchId ?? 0;

            var claims = new List<Claim>
                {
                    new Claim(ClaimTypes.Name, user.UserName),
					//new Claim(ClaimTypes.Role, user.Role ?? ""), // Legacy
                    new Claim("UserId", $"{user.UserMasterId}"),
                    new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
                    new Claim("UserRole", user.Role ?? ""),
					//new Claim("RoleId", roleId.ToString()),
					new Claim("UserEmpId", (user.EmployeeMasterId ?? 0).ToString()),
                    new Claim("CompanyId", user.CompanyMasterId.ToString() ?? "-1"),
                    new Claim("BranchId", branchId.ToString()),
                };

            // Fetch ONLY the PermissionVersion for Cache Validation in the Token
            int userId = (int)user.UserMasterId;
            int permissionVersion = await _permissionResolver.GetUserPermissionVersionAsync(userId);
            claims.Add(new Claim("PermissionVersion", permissionVersion.ToString()));

            // Add Role claims specifically (Required if you ever use User.IsInRole("Admin") in .NET)
            var roles = await _permissionResolver.GetUserRolesAsync(userId);
            if (roles != null)
            {
                foreach (var r in roles)
                {
                    claims.Add(new Claim(ClaimTypes.Role, r));
                }
            }

            // Create a JWT token with issuer, audience, expiration time, and signing credentials
            var token = new JwtSecurityToken(
                _configuration["Jwt:Issuer"],
                _configuration["Jwt:Audience"],
                claims,
                expires: DateTime.Now.AddMinutes(240), // Expiration time (240 minutes from now, 4 Hours)
                signingCredentials: credentials // Signing credentials
            );

            // Write the token as a string using JwtSecurityTokenHandler
            return new JwtSecurityTokenHandler().WriteToken(token);
        }
