namespace SolutionOne_Core.MultiTenancy
{
    /// <summary>
    /// One row of the tenant catalogue (HR_Master.dbo.HR_ClientRegistry), as resolved for the
    /// current request. This is the IDENTITY of a customer's database - never its credentials.
    ///
    /// The catalogue is shared with the legacy SolutionOneWeb payroll app, which reads the same
    /// registry rows. Both applications point at the SAME physical database per customer, but each
    /// builds its own connection string from its own local template, so each keeps its own SQL
    /// login. That is why <see cref="ConnectionString"/> is NOT carried here: see TenantRegistry.
    /// </summary>
    public sealed class TenantInfo
    {
        /// <summary>HR_ClientRegistry.ClientID - the stable tenant id written into the JWT.</summary>
        public int ClientId { get; init; }

        /// <summary>Short human-readable code, e.g. "ACME". Used for log correlation and cache keys.</summary>
        public string ClientCode { get; init; } = string.Empty;

        /// <summary>Initial Catalog of this tenant's database.</summary>
        public string DatabaseName { get; init; } = string.Empty;

        /// <summary>
        /// False when the subscription is suspended. Deliberately NOT filtered out in the registry
        /// query: a suspended tenant must be distinguishable from an unknown product key, so the
        /// caller can answer 403 rather than 404.
        /// </summary>
        public bool IsActive { get; init; }

        /// <summary>
        /// Highest applied migration number for this tenant, or null when not yet tracked.
        /// Populated by the migration consolidation work (planned separately); until then the
        /// column is null for every row and callers must treat it as "unknown", not "zero".
        /// </summary>
        public int? SchemaVersion { get; init; }
    }
}
