namespace SolutionOne_Core.MultiTenancy
{
    /// <summary>
    /// The tenant this request belongs to. Scoped: populated once by TenantResolutionMiddleware
    /// (or, on the login path, by the controller once the product key has been validated) and read
    /// by everything that opens a database connection.
    ///
    /// This is the ONLY thing that decides which customer database the request touches, which is
    /// why it fails closed: <see cref="ConnectionString"/> throws rather than falling back to a
    /// default when nothing has been resolved. A silent fallback here would serve one customer's
    /// data to another.
    /// </summary>
    public interface ITenantContext
    {
        /// <summary>True once a tenant has been resolved for this request.</summary>
        bool IsResolved { get; }

        /// <summary>
        /// True when multi-tenancy is switched off (MultiTenancy:Enabled = false), in which case
        /// the single configured WebPortalConnectionString is used and <see cref="Tenant"/> is null.
        /// Mirrors the legacy app's EnableMultiTenant = false mode so a single-customer deployment
        /// behaves exactly as it does today.
        /// </summary>
        bool IsSingleTenantMode { get; }

        /// <summary>The resolved tenant, or null in single-tenant mode.</summary>
        TenantInfo? Tenant { get; }

        /// <summary>
        /// Connection string for this request's database. Throws <see cref="TenantResolutionException"/>
        /// when no tenant has been resolved - never returns a default.
        /// </summary>
        string ConnectionString { get; }

        /// <summary>
        /// Prefix that must be applied to every process-wide cache key. IMemoryCache is a singleton
        /// shared by every tenant, so an unprefixed key leaks one customer's data to the next.
        /// Use ITenantCache rather than calling this directly.
        /// </summary>
        string CacheKeyPrefix { get; }
    }

    /// <summary>
    /// Mutation side of <see cref="ITenantContext"/>, kept separate so that only the resolution
    /// middleware and the login controller can set a tenant - repositories inject the read-only
    /// interface and cannot redirect themselves at another customer's database.
    /// </summary>
    public interface ITenantContextSetter
    {
        void SetTenant(TenantInfo tenant, string connectionString);
    }
}
