    public sealed class MultiTenancyOptions
    {
        public const string SectionName = "MultiTenancy";

        /// <summary>
        /// Master switch, mirroring the legacy app's EnableMultiTenant appSetting.
        ///
        /// false = every request uses ConnectionStrings:WebPortalConnectionString, exactly as
        ///         before this feature existed. The catalogue is never opened. This is the default
        ///         so an existing single-customer deployment is unaffected by deploying this build.
        /// true  = the product key / tenant claim selects the database from the catalogue, and a
        ///         request that resolves no tenant is refused.
        /// </summary>
        public bool Enabled { get; set; }

        /// <summary>
        /// AES-encrypted connection string for the catalogue database (HR_Master), encrypted with
        /// the same key as WebPortalConnectionString. Only this application reads it; the legacy
        /// app no longer needs any rights on HR_Master once it resolves over the API.
        /// </summary>
        public string? MasterConnectionString { get; set; }

        /// <summary>
        /// AES-encrypted connection string template. Its Initial Catalog is replaced with the
        /// resolved tenant's DatabaseName; every other part (server, credentials, pooling) is kept.
        ///
        /// This is what keeps SQL credentials out of the catalogue: the catalogue stores only which
        /// database a customer uses, and each application supplies its own login for it.
        /// </summary>
        public string? ClientConnectionTemplate { get; set; }

        /// <summary>How long a resolved catalogue row is cached. Matches the legacy app's 10 minutes.</summary>
        public int CacheMinutes { get; set; } = 10;

        /// <summary>
        /// Max Pool Size forced onto every tenant connection string. ADO.NET pools per distinct
        /// connection string, so N tenants at the default 100 would allow N*100 connections against
        /// the cluster. 0 leaves whatever the template specifies.
        /// </summary>
        public int MaxPoolSizePerTenant { get; set; } = 30;
    }
}
