    /// Generation, normalisation and hashing of the product key a customer types once at login.
    ///
    /// The key SELECTS a database; the user's password still authenticates them. So a leaked key
    /// reveals that a tenant exists, not its data - but it is still a credential, which is why only
    /// its hash is stored and why keys are revocable per row rather than being a column on the
    /// tenant.
    /// </summary>
    public static class ProductKey
    {
        /// <summary>
        /// Crockford base32: no I, L, O or U, so a key cannot be mistyped by confusing 1/I/L or
        /// 0/O, and it contains no vowels that could form words. 25 characters = 125 bits.
        /// </summary>
        private const string Alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

        private const string DisplayPrefix = "SO1";
        private const int PayloadLength = 25;
        private const int GroupSize = 5;

        /// <summary>
        /// A new key in display form, e.g. SO1-7K2M9-4FHT2-BWYQX-3NRVD-8PGSJ.
        /// Uses rejection-free indexing into a 32-character alphabet (32 divides 256), so every
        /// character is uniformly distributed - no modulo bias.
        /// </summary>
        public static string Generate()
        {
            Span<byte> bytes = stackalloc byte[PayloadLength];
            RandomNumberGenerator.Fill(bytes);

            var payload = new char[PayloadLength];
            for (int i = 0; i < PayloadLength; i++)
            {
                payload[i] = Alphabet[bytes[i] & 0x1F];
            }

            return Format(new string(payload));
        }

        /// <summary>
        /// Groups a 25-character payload into the hyphenated display form.
        /// </summary>
        public static string Format(string payload)
        {
            if (string.IsNullOrEmpty(payload) || payload.Length != PayloadLength)
            {
                throw new ArgumentException($"Product key payload must be {PayloadLength} characters.", nameof(payload));
            }

            var sb = new StringBuilder(DisplayPrefix);
            for (int i = 0; i < PayloadLength; i += GroupSize)
            {
                sb.Append('-').Append(payload, i, GroupSize);
            }

            return sb.ToString();
        }

        /// <summary>
        /// Reduces whatever the user typed to the canonical 25-character payload, or null if it
        /// could not possibly be a key. Tolerates lower case, missing or extra hyphens, surrounding
        /// whitespace, a missing SO1 prefix, and the four characters Crockford excludes (I and L
        /// read as 1, O as 0) - all of which are things people actually type when copying a key off
        /// an email or a licence certificate.
        /// </summary>
        public static string? Normalize(string? input)
        {
            if (string.IsNullOrWhiteSpace(input))
            {
                return null;
            }

            var sb = new StringBuilder(PayloadLength);
            foreach (char raw in input)
            {
                char c = char.ToUpperInvariant(raw);

                // Separators and anything else non-alphanumeric is formatting, not payload.
                if (!char.IsLetterOrDigit(c))
                {
                    continue;
                }

                c = c switch
                {
                    'I' or 'L' => '1',
                    'O' => '0',
                    'U' => 'V', // Crockford's documented substitution
                    _ => c
                };

                if (Alphabet.IndexOf(c) < 0)
                {
                    return null;
                }

                sb.Append(c);
            }

            string candidate = sb.ToString();

            // The display prefix survives the strip above (S, 0 and 1 are all in the alphabet), so
            // remove it only when its presence makes the length correct.
            if (candidate.Length == DisplayPrefix.Length + PayloadLength &&
                candidate.StartsWith(DisplayPrefix, StringComparison.Ordinal))
            {
                candidate = candidate.Substring(DisplayPrefix.Length);
            }

            return candidate.Length == PayloadLength ? candidate : null;
        }

        /// <summary>
        /// Lower-case hex SHA-256 of the normalised payload - what HR_ClientProductKey.KeyHash
        /// stores and what the registry looks up.
        ///
        /// A plain hash, not bcrypt/PBKDF2, on purpose: lookup has to be a single indexed equality
        /// match against an unknown tenant, and a per-row salt would force a scan of every key in
        /// the catalogue on every login. That is an acceptable trade here only because the input is
        /// 125 bits of uniform randomness, so there is no dictionary to run against it.
        /// </summary>
        public static string Hash(string normalizedPayload)
        {
            if (string.IsNullOrEmpty(normalizedPayload))
            {
                throw new ArgumentException("Product key payload is required.", nameof(normalizedPayload));
            }

            byte[] digest = SHA256.HashData(Encoding.UTF8.GetBytes(normalizedPayload));
            return Convert.ToHexString(digest).ToLowerInvariant();
        }

        /// <summary>
        /// Normalise then hash in one step. Returns null when the input is not a well-formed key,
        /// so callers can reject it without ever touching the catalogue.
        /// </summary>
        public static string? NormalizeAndHash(string? input)
        {
            string? normalized = Normalize(input);
            return normalized is null ? null : Hash(normalized);
        }
    }
}
