namespace SolutionOne_Core.MultiTenancy
{
    /// <summary>
    /// The decrypted, validated multi-tenancy settings, built once at startup and held as a
    /// singleton.
    ///
    /// Decryption happens here and nowhere else so the AES password is handled in a single place
    /// rather than being re-read and re-decrypted on every request (which is what DapperContext and
    /// HrmsystemContext.OnConfiguring each used to do independently).
    /// </summary>
    public sealed class TenantRuntimeConfig
    {
        /// <summary>Multi-tenancy master switch. False = behave exactly as a single-customer build.</summary>
        public bool Enabled { get; init; }

        /// <summary>
        /// ConnectionStrings:WebPortalConnectionString, decrypted. The only database used when
        /// <see cref="Enabled"/> is false; unused otherwise.
        /// </summary>
        public string? DefaultConnectionString { get; init; }

        /// <summary>Catalogue (HR_Master) connection string, decrypted. Required when enabled.</summary>
        public string? MasterConnectionString { get; init; }

        /// <summary>
        /// Per-tenant connection template, decrypted. Initial Catalog is swapped per tenant; the
        /// credentials in it are this application's own and never leave the server.
        /// </summary>
        public string? ClientConnectionTemplate { get; init; }

        public int CacheMinutes { get; init; } = 10;

        public int MaxPoolSizePerTenant { get; init; } = 30;
    }
}
