using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// Scoped holder for the request's tenant. Written once by TenantResolutionMiddleware (or by
    /// LoginController once a product key has been validated), read by HrmsystemContext,
    /// DapperContext and DbConnectionConfig when they are first resolved in the scope - which
    /// always happens after the middleware has run.
    /// </summary>
    public sealed class TenantContext : ITenantContext, ITenantContextSetter
    {
        private readonly TenantRuntimeConfig _config;
        private string? _connectionString;

        public TenantContext(TenantRuntimeConfig config)
        {
            _config = config;
        }

        public TenantInfo? Tenant { get; private set; }

        public bool IsSingleTenantMode => !_config.Enabled;

        public bool IsResolved => IsSingleTenantMode || Tenant is not null;

        public string ConnectionString
        {
            get
            {
                if (IsSingleTenantMode)
                {
                    return _config.DefaultConnectionString
                        ?? throw new TenantResolutionException(
                            "Multi-tenancy is disabled but ConnectionStrings:WebPortalConnectionString is missing or could not be decrypted.");
                }

                if (_connectionString is null)
                {
                    // Fail closed. Falling back to a default connection string here would run the
                    // request against whichever database the server happens to be configured for,
                    // and the caller would never know it got the wrong customer's data.
                    throw new TenantResolutionException(
                        "No tenant has been resolved for this request. A valid product key (at login) " +
                        "or a tenant claim (on an authenticated request) is required.");
                }

                return _connectionString;
            }
        }

        /// <summary>
        /// Prefix for every process-wide cache entry. The client code is included only to make
        /// cache dumps readable; the numeric id is what guarantees uniqueness.
        /// </summary>
        public string CacheKeyPrefix =>
            IsSingleTenantMode ? "t0::" : $"t{Tenant?.ClientId ?? 0}::";

        public void SetTenant(TenantInfo tenant, string connectionString)
        {
            ArgumentNullException.ThrowIfNull(tenant);

            if (string.IsNullOrWhiteSpace(connectionString))
            {
                throw new ArgumentException("Connection string is required.", nameof(connectionString));
            }

            // Set-once. A second write would mean something tried to move an in-flight request to a
            // different database after repositories may already have read from the first one.
            if (Tenant is not null && Tenant.ClientId != tenant.ClientId)
            {
                throw new TenantResolutionException(
                    $"Request is already bound to tenant {Tenant.ClientId}; it cannot be re-bound to {tenant.ClientId}.");
            }

            Tenant = tenant;
            _connectionString = connectionString;
        }
    }
}
