using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// Reads the tenant catalogue (HR_Master.dbo.HR_ClientRegistry + HR_ClientProductKey).
    ///
    /// Shared with the legacy SolutionOneWeb payroll app, which reads the same registry rows - so
    /// the two applications always agree on which database a customer uses. Legacy reaches it
    /// through this application's /api/Tenant/Resolve endpoint rather than connecting to HR_Master
    /// itself.
    /// </summary>
    public interface ITenantRegistry
    {
        /// <summary>
        /// Resolve a tenant from the key the customer typed. Returns null when the key is unknown
        /// or malformed; returns the tenant with IsActive = false when the subscription is
        /// suspended, so callers can tell "wrong key" from "suspended account".
        /// </summary>
        Task<TenantInfo?> ResolveByProductKeyAsync(string? productKey, CancellationToken cancellationToken = default);

        /// <summary>Resolve by the ClientID carried in a validated JWT.</summary>
        Task<TenantInfo?> ResolveByClientIdAsync(int clientId, CancellationToken cancellationToken = default);

        /// <summary>Every active tenant. For background work, which has no request to take a tenant from.</summary>
        Task<IReadOnlyList<TenantInfo>> GetActiveTenantsAsync(CancellationToken cancellationToken = default);

        /// <summary>
        /// This application's connection string for a tenant: the local template with Initial
        /// Catalog swapped. The catalogue never supplies credentials.
        /// </summary>
        string BuildConnectionString(TenantInfo tenant);

        /// <summary>Drops the cached catalogue row for a tenant, e.g. after a key is revoked.</summary>
        void Invalidate(int clientId);
    }
}
