using Dapper;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// Catalogue reader. Singleton: it holds no per-request state and its cache is deliberately
    /// process-wide, since the tenant map is small, identical for every request and changes only
    /// when a subscription does.
    /// </summary>
    public sealed class TenantRegistry : ITenantRegistry
    {
        // The legacy app selects these same columns from the same table (see
        // SolutionOneWeb/App_Code/DbConnectionFactory.cs). ConnectionString is deliberately NOT
        // selected: this application builds its own from the local template so that catalogue
        // compromise never yields a SQL login. The column stays in the table for the legacy app,
        // which still reads it on servers that have not yet moved to key-based resolution.
        private const string SelectColumns =
            "r.ClientID, r.ClientCode, r.DatabaseName, r.IsActive, r.SchemaVersion";

        private const string KeyCachePrefix = "__tenantreg::key::";
        private const string IdCachePrefix = "__tenantreg::id::";

        private readonly TenantRuntimeConfig _config;
        private readonly IMemoryCache _cache;
        private readonly ILogger<TenantRegistry> _logger;

        public TenantRegistry(TenantRuntimeConfig config, IMemoryCache cache, ILogger<TenantRegistry> logger)
        {
            _config = config;
            _cache = cache;
            _logger = logger;
        }

        public async Task<TenantInfo?> ResolveByProductKeyAsync(string? productKey, CancellationToken cancellationToken = default)
        {
            // Reject anything that is not a well-formed key before touching the catalogue, so a
            // stream of junk costs nothing but a hash.
            string? keyHash = ProductKey.NormalizeAndHash(productKey);
            if (keyHash is null)
            {
                return null;
            }

            string cacheKey = KeyCachePrefix + keyHash;
            if (_cache.TryGetValue(cacheKey, out TenantInfo? cached) && cached is not null)
            {
                return cached;
            }

            const string sql = $@"
                SELECT TOP 1 {SelectColumns}
                FROM dbo.HR_ClientProductKey k
                INNER JOIN dbo.HR_ClientRegistry r ON r.ClientID = k.ClientID
                WHERE k.KeyHash = @KeyHash
                  AND k.IsActive = 1
                  AND k.RevokedOn IS NULL;";

            TenantInfo? tenant = await QuerySingleAsync(sql, new { KeyHash = keyHash }, cancellationToken);
            if (tenant is not null)
            {
                Cache(cacheKey, tenant);
                Cache(IdCachePrefix + tenant.ClientId, tenant);
            }

            return tenant;
        }

        public async Task<TenantInfo?> ResolveByClientIdAsync(int clientId, CancellationToken cancellationToken = default)
        {
            if (clientId <= 0)
            {
                return null;
            }

            string cacheKey = IdCachePrefix + clientId;
            if (_cache.TryGetValue(cacheKey, out TenantInfo? cached) && cached is not null)
            {
                return cached;
            }

            const string sql = $@"
                SELECT TOP 1 {SelectColumns}
                FROM dbo.HR_ClientRegistry r
                WHERE r.ClientID = @ClientID;";

            TenantInfo? tenant = await QuerySingleAsync(sql, new { ClientID = clientId }, cancellationToken);
            if (tenant is not null)
            {
                Cache(cacheKey, tenant);
            }

            return tenant;
        }

        public async Task<IReadOnlyList<TenantInfo>> GetActiveTenantsAsync(CancellationToken cancellationToken = default)
        {
            const string sql = $@"
                SELECT {SelectColumns}
                FROM dbo.HR_ClientRegistry r
                WHERE r.IsActive = 1
                ORDER BY r.ClientCode;";

            await using var connection = new SqlConnection(RequireMasterConnectionString());
            var rows = await connection.QueryAsync<TenantRow>(
                new CommandDefinition(sql, cancellationToken: cancellationToken));

            return rows.Select(ToTenantInfo).ToList();
        }

        public string BuildConnectionString(TenantInfo tenant)
        {
            ArgumentNullException.ThrowIfNull(tenant);

            if (string.IsNullOrWhiteSpace(_config.ClientConnectionTemplate))
            {
                throw new TenantResolutionException(
