        {
            ArgumentNullException.ThrowIfNull(tenant);

            if (string.IsNullOrWhiteSpace(_config.ClientConnectionTemplate))
            {
                throw new TenantResolutionException(
                    "MultiTenancy:ClientConnectionTemplate is not configured, so no tenant connection can be built.");
            }

            if (string.IsNullOrWhiteSpace(tenant.DatabaseName))
            {
                throw new TenantResolutionException(
                    $"Tenant {tenant.ClientCode} (ClientID {tenant.ClientId}) has no DatabaseName in the catalogue.");
            }

