            // can each open the default 100 connections against the same cluster.
            if (_config.MaxPoolSizePerTenant > 0)
            {
                builder.MaxPoolSize = _config.MaxPoolSizePerTenant;
            }

            // DapperContext and several repositories read overlapping result sets on one connection.
            builder.MultipleActiveResultSets = true;

            return builder.ConnectionString;
        }

        public void Invalidate(int clientId)
        {
            _cache.Remove(IdCachePrefix + clientId);
            // Key-hash entries cannot be enumerated from IMemoryCache, so they are left to expire.
            // That bounds how long a revoked key keeps working to CacheMinutes, which is why the
            // window is short and why revocation is not an emergency control on its own.
        }

        private async Task<TenantInfo?> QuerySingleAsync(string sql, object parameters, CancellationToken cancellationToken)
        {
