                    new CommandDefinition(sql, parameters, cancellationToken: cancellationToken));

                return row is null ? null : ToTenantInfo(row);
            }
            catch (SqlException ex)
            {
                // Never swallow this into "tenant not found": an unreachable catalogue would then
                // look exactly like a wrong product key, and every customer would be told their
                // licence is invalid during an outage.
                _logger.LogError(ex, "Tenant catalogue lookup failed against HR_Master.");
                throw new TenantResolutionException(
                    "The tenant catalogue is unavailable. Please try again shortly.");
            }
        }

        private void Cache(string cacheKey, TenantInfo tenant) =>
            _cache.Set(cacheKey, tenant, TimeSpan.FromMinutes(Math.Max(1, _config.CacheMinutes)));

        private string RequireMasterConnectionString() =>
            string.IsNullOrWhiteSpace(_config.MasterConnectionString)
                ? throw new TenantResolutionException(
                    "MultiTenancy:MasterConnectionString is not configured, so the tenant catalogue cannot be read.")
                : _config.MasterConnectionString;

        private static TenantInfo ToTenantInfo(TenantRow row) => new()
        {
            ClientId = row.ClientID,
            ClientCode = row.ClientCode ?? string.Empty,
            DatabaseName = row.DatabaseName ?? string.Empty,
            IsActive = row.IsActive,
            SchemaVersion = row.SchemaVersion
        };

        private sealed class TenantRow
        {
