using Microsoft.Extensions.Caching.Memory;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// IMemoryCache scoped to the current tenant.
    ///
    /// IMemoryCache is a process-wide singleton, so a key like "UserPermissions_42" means user 42
    /// of WHICHEVER customer wrote it first - every later tenant reads that entry back as its own.
    /// Nothing errors; the wrong data is simply served. Every cache site in the DAL injects this
    /// instead of IMemoryCache so the prefix cannot be forgotten at a call site.
    /// </summary>
    public interface ITenantCache
    {
        bool TryGetValue<T>(string key, out T? value);

        void Set<T>(string key, T value, TimeSpan absoluteExpirationRelativeToNow);

        void Set<T>(string key, T value, MemoryCacheEntryOptions options);

        void Remove(string key);

        Task<T> GetOrCreateAsync<T>(string key, Func<ICacheEntry, Task<T>> factory);
    }
}
