using Microsoft.Extensions.Caching.Memory;
using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// Prefixes every key with the request's tenant before handing it to the shared IMemoryCache.
    /// Scoped, because the prefix comes from the scoped ITenantContext.
    /// </summary>
    public sealed class TenantCache : ITenantCache
    {
        private readonly IMemoryCache _inner;
        private readonly ITenantContext _tenant;

        public TenantCache(IMemoryCache inner, ITenantContext tenant)
        {
            _inner = inner;
            _tenant = tenant;
        }

        public bool TryGetValue<T>(string key, out T? value) =>
            _inner.TryGetValue(Scope(key), out value);

        public void Set<T>(string key, T value, TimeSpan absoluteExpirationRelativeToNow) =>
            _inner.Set(Scope(key), value, absoluteExpirationRelativeToNow);

        public void Set<T>(string key, T value, MemoryCacheEntryOptions options) =>
            _inner.Set(Scope(key), value, options);

        public void Remove(string key) => _inner.Remove(Scope(key));

        public Task<T> GetOrCreateAsync<T>(string key, Func<ICacheEntry, Task<T>> factory) =>
            _inner.GetOrCreateAsync(Scope(key), factory)!;

        /// <summary>
        /// In single-tenant mode this is a constant prefix, so behaviour is unchanged apart from
        /// the key text. In multi-tenant mode an unresolved tenant would silently collapse every
        /// customer onto one prefix, so ITenantContext.CacheKeyPrefix is read only after resolution
        /// - any cache use on an unresolved request is a bug worth surfacing rather than hiding.
        /// </summary>
        private string Scope(string key) => _tenant.CacheKeyPrefix + key;
    }
}
