using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.MultiTenancy;
using SolutionOne_DataAccessLayer.MultiTenancy;

namespace SolutionOne_DataAccessLayer.Middleware.MultiTenancy
{
    /// <summary>
    /// Registers tenant resolution. Call before AddDbContext, which depends on ITenantContext.
    /// </summary>
    public static class MultiTenancyDependencyInjection
    {
        /// <summary>
        /// Same AES password as ConnectionStrings:WebPortalConnectionString uses in Program.cs,
        /// HrmsystemContext.OnConfiguring, DapperContext and DbConnectionFactory. It is hard-coded
        /// in all of those today; this does not make that worse, but it should move to an
        /// environment variable before the catalogue holds more than one customer's details.
        /// </summary>
        private const string EncryptionKey = "Gsspl@2024Gsspl@";

        public static IServiceCollection AddMultiTenancy(this IServiceCollection services, IConfiguration configuration)
        {
            var options = new MultiTenancyOptions();
            configuration.GetSection(MultiTenancyOptions.SectionName).Bind(options);

            var aes = new AESEncryption(configuration);

            var runtime = new TenantRuntimeConfig
            {
                Enabled = options.Enabled,
                DefaultConnectionString = Decrypt(aes, configuration.GetConnectionString("WebPortalConnectionString")),
                MasterConnectionString = Decrypt(aes, options.MasterConnectionString),
                ClientConnectionTemplate = Decrypt(aes, options.ClientConnectionTemplate),
                CacheMinutes = options.CacheMinutes,
                MaxPoolSizePerTenant = options.MaxPoolSizePerTenant
            };

            // Fail at startup rather than on the first customer request: a server configured for
            // multi-tenancy without a catalogue would otherwise boot happily and then refuse every
            // login with a runtime error.
            if (runtime.Enabled)
            {
                if (string.IsNullOrWhiteSpace(runtime.MasterConnectionString))
                {
                    throw new InvalidOperationException(
                        "MultiTenancy:Enabled is true but MultiTenancy:MasterConnectionString is missing or could not be decrypted.");
                }

                if (string.IsNullOrWhiteSpace(runtime.ClientConnectionTemplate))
                {
                    throw new InvalidOperationException(
                        "MultiTenancy:Enabled is true but MultiTenancy:ClientConnectionTemplate is missing or could not be decrypted.");
                }
            }

            services.AddSingleton(runtime);
            services.AddMemoryCache();
            services.AddSingleton<ITenantRegistry, TenantRegistry>();

            // One instance per request implementing both faces: repositories take ITenantContext
            // (read-only), the resolution middleware and LoginController take ITenantContextSetter.
            services.AddScoped<TenantContext>();
            services.AddScoped<ITenantContext>(sp => sp.GetRequiredService<TenantContext>());
            services.AddScoped<ITenantContextSetter>(sp => sp.GetRequiredService<TenantContext>());

            services.AddScoped<ITenantCache, TenantCache>();

            return services;
        }

        /// <summary>
        /// Values are stored AES-encrypted exactly as WebPortalConnectionString is. A value that is
        /// already plaintext (a developer pasting one in while testing) is passed through rather
        /// than mangled, which is what the "Data Source=" probe is for.
        /// </summary>
        private static string? Decrypt(AESEncryption aes, string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return null;
            }

            if (value.Contains("Data Source=", StringComparison.OrdinalIgnoreCase))
            {
                return value;
            }

            try
            {
                return aes.Decrypt(value, EncryptionKey);
            }
            catch
            {
                // A value that will not decrypt is a configuration error, surfaced by the Enabled
                // checks above rather than by throwing out of a Decrypt helper.
                return null;
            }
        }
    }
}
