using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    public enum TenantBindStatus
    {
        /// <summary>Tenant resolved and bound to this request.</summary>
        Success,

        /// <summary>Multi-tenancy is off; the single configured database is in use.</summary>
        SingleTenant,

        /// <summary>No product key / tenant claim was supplied.</summary>
        Missing,

        /// <summary>The key or client id does not exist in the catalogue.</summary>
        NotFound,

        /// <summary>The tenant exists but its subscription is not active.</summary>
        Suspended
    }

    public sealed record TenantBindResult(TenantBindStatus Status, TenantInfo? Tenant)
    {
        public bool IsSuccess => Status is TenantBindStatus.Success or TenantBindStatus.SingleTenant;
    }

    /// <summary>
    /// Looks a tenant up and binds it to the current request. Used by TenantResolutionMiddleware
    /// for ordinary requests and directly by LoginController, where the key arrives in the request
    /// body rather than a header.
    /// </summary>
    public interface ITenantResolutionService
    {
        Task<TenantBindResult> BindFromProductKeyAsync(string? productKey, CancellationToken cancellationToken = default);

        Task<TenantBindResult> BindFromClientIdAsync(int clientId, CancellationToken cancellationToken = default);
    }

    public sealed class TenantResolutionService : ITenantResolutionService
    {
        private readonly ITenantRegistry _registry;
        private readonly ITenantContext _context;
        private readonly ITenantContextSetter _setter;

        public TenantResolutionService(ITenantRegistry registry, ITenantContext context, ITenantContextSetter setter)
        {
            _registry = registry;
            _context = context;
            _setter = setter;
        }

        public Task<TenantBindResult> BindFromProductKeyAsync(string? productKey, CancellationToken cancellationToken = default) =>
            BindAsync(() => _registry.ResolveByProductKeyAsync(productKey, cancellationToken),
                      string.IsNullOrWhiteSpace(productKey));

        public Task<TenantBindResult> BindFromClientIdAsync(int clientId, CancellationToken cancellationToken = default) =>
            BindAsync(() => _registry.ResolveByClientIdAsync(clientId, cancellationToken),
                      clientId <= 0);

        private async Task<TenantBindResult> BindAsync(Func<Task<TenantInfo?>> lookup, bool inputMissing)
        {
            if (_context.IsSingleTenantMode)
            {
                return new TenantBindResult(TenantBindStatus.SingleTenant, null);
            }

            if (inputMissing)
            {
                return new TenantBindResult(TenantBindStatus.Missing, null);
            }

            TenantInfo? tenant = await lookup();
            if (tenant is null)
            {
                return new TenantBindResult(TenantBindStatus.NotFound, null);
            }

            // Checked on every request, not only at login, so a suspended subscription takes effect
            // within one cache period instead of waiting for the user's 4-hour token to expire.
            if (!tenant.IsActive)
            {
                return new TenantBindResult(TenantBindStatus.Suspended, tenant);
            }

            _setter.SetTenant(tenant, _registry.BuildConnectionString(tenant));
            return new TenantBindResult(TenantBindStatus.Success, tenant);
        }
    }
}
