namespace SolutionOne_Core.MultiTenancy
{
    /// <summary>
    /// Claims that carry the tenant inside the signed JWT.
    ///
    /// Once issued at login, this is the ONLY source of tenant identity for an authenticated
    /// request. The product key is never re-read from a later request body or header: if it were,
    /// a user logged into one customer could present another customer's key and point their own
    /// authenticated session at that database.
    /// </summary>
    public static class TenantClaimTypes
    {
        public const string TenantId = "tenant_id";
        public const string TenantCode = "tenant_code";

        /// <summary>
        /// Header carrying the product key on requests that have no token yet - login, and the
        /// legacy payroll app's catalogue lookup. Ignored whenever a tenant claim is present.
        /// </summary>
        public const string ProductKeyHeader = "X-Product-Key";
    }
}
