using System.Net;
using System.Text.Json;
using SolutionOne_Core.MultiTenancy;
using SolutionOne_DataAccessLayer.MultiTenancy;

namespace SolutionOneWebPortal_API.MultiTenancy
{
    /// <summary>
    /// Binds each request to a tenant before any repository can open a connection.
    ///
    /// Must run AFTER UseAuthentication (the tenant claim has to be validated first) and BEFORE
    /// MapControllers. HrmsystemContext, DapperContext and DbConnectionConfig are all resolved
    /// lazily inside the request scope, so they pick up whatever this middleware bound.
    /// </summary>
    public sealed class TenantResolutionMiddleware : IMiddleware
    {
        private readonly ITenantContext _tenantContext;
        private readonly ILogger<TenantResolutionMiddleware> _logger;

        public TenantResolutionMiddleware(ITenantContext tenantContext, ILogger<TenantResolutionMiddleware> logger)
        {
            _tenantContext = tenantContext;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context, RequestDelegate next)
        {
            if (_tenantContext.IsSingleTenantMode)
            {
                await next(context);
                return;
            }

            var resolver = context.RequestServices.GetRequiredService<ITenantResolutionService>();

            // 1. A validated tenant claim always wins. Checking this first is what stops a logged-in
            //    user of one customer from redirecting their session with someone else's key.
            string? claimValue = context.User?.FindFirst(TenantClaimTypes.TenantId)?.Value;
            if (!string.IsNullOrWhiteSpace(claimValue))
            {
                if (!int.TryParse(claimValue, out int clientId))
                {
                    await WriteProblem(context, HttpStatusCode.Unauthorized,
                        "The session's tenant claim is not valid. Please sign in again.");
                    return;
                }

                TenantBindResult claimResult = await resolver.BindFromClientIdAsync(clientId, context.RequestAborted);
                if (!await HandleFailure(context, claimResult, viaClaim: true))
                {
                    return;
                }

                await next(context);
                return;
            }

            // 2. No token yet. A product key header bootstraps the tenant for anonymous calls -
            //    login, and the legacy payroll app's /api/Tenant/Resolve lookup.
            string? productKey = context.Request.Headers[TenantClaimTypes.ProductKeyHeader].FirstOrDefault();
            if (!string.IsNullOrWhiteSpace(productKey))
            {
                TenantBindResult keyResult = await resolver.BindFromProductKeyAsync(productKey, context.RequestAborted);
                if (!await HandleFailure(context, keyResult, viaClaim: false))
                {
                    return;
                }
            }

            // 3. Nothing to bind. Deliberately NOT an error here: Swagger, static files and the
            //    login endpoint (which takes its key from the request body) all legitimately reach
            //    this point. Anything that then tries to touch a database throws
            //    TenantResolutionException, which GlobalExceptionHandler turns into a 401.
            await next(context);
        }

        /// <summary>Returns true when the request may continue.</summary>
        private async Task<bool> HandleFailure(HttpContext context, TenantBindResult result, bool viaClaim)
        {
            switch (result.Status)
            {
                case TenantBindStatus.Success:
                case TenantBindStatus.SingleTenant:
                    return true;

                case TenantBindStatus.Suspended:
                    _logger.LogWarning("Request refused: tenant {ClientCode} ({ClientId}) is not active.",
                        result.Tenant?.ClientCode, result.Tenant?.ClientId);
                    await WriteProblem(context, HttpStatusCode.Forbidden,
                        "This subscription is not active. Please contact your administrator.");
                    return false;

                case TenantBindStatus.NotFound:
                    // Logged without the key itself - it is a credential and does not belong in logs.
                    _logger.LogWarning("Request refused: no catalogue entry for the supplied {Source}.",
                        viaClaim ? "tenant claim" : "product key");
                    await WriteProblem(context, HttpStatusCode.Unauthorized, viaClaim
                        ? "This session is no longer valid. Please sign in again."
                        : "Invalid product key.");
                    return false;

                default:
                    await WriteProblem(context, HttpStatusCode.Unauthorized, "A product key is required.");
                    return false;
            }
        }

        /// <summary>
        /// Shaped like the ResponseModel the Angular client's error interceptor already reads, so a
        /// refused tenant surfaces as a toast rather than "Something went wrong".
        /// </summary>
        private static async Task WriteProblem(HttpContext context, HttpStatusCode status, string message)
        {
            context.Response.StatusCode = (int)status;
            context.Response.ContentType = "application/json";

            await context.Response.WriteAsync(JsonSerializer.Serialize(new
            {
                IsSuccess = false,
                Status = (int)status,
                Message = message
            }));
        }
    }
}
