﻿using Microsoft.AspNetCore.Diagnostics;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.Exceptions;
using SolutionOneWebPortal_API.Debugging;
using System.Net;
using Serilog;

namespace SolutionOneWebPortal_API.Exceptions
{
    public class GlobalExceptionHandler : IExceptionHandler
    {
        private readonly ILogger<GlobalExceptionHandler> _logger;
        private readonly DebugModeOptions _dbg;

        public GlobalExceptionHandler(
            ILogger<GlobalExceptionHandler> logger,
            DebugModeOptions dbg
        )
        {
            _logger = logger;
            _dbg = dbg;
        }

        public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
        {
            _logger.LogError(exception, exception.Message);
            if (_dbg.Enabled)
            {
                Log.Debug(exception,
                    "UNHANDLED at {Path}{Query} | Route: {@Route}",
                    httpContext.Request.Path,
                    httpContext.Request.QueryString,
                    httpContext.Request.RouteValues);
            }
            var response = new ErrorResponse
            {
                Message = exception.Message,
            };

            switch (exception)
            {
                case BadHttpRequestException:
                    response.StatusCode = (int)HttpStatusCode.BadRequest;
                    response.Titel = exception.GetType().Name;
                    break;

                // The caller's token did not carry a claim a service needed (CompanyId, UserId,
                // ...) - resolved centrally here so every service built on IRequestMetadata gets
                // the same 401 shape instead of each one inventing its own "no company on this
                // token" response. See MissingClaimException's remarks for why services must not
                // catch this locally.
                case MissingClaimException:
                    response.StatusCode = (int)HttpStatusCode.Unauthorized;
                    response.Titel = "Unauthorized";
                    break;

                // Thrown by the service-layer permission guard for methods that cannot return a 403
                // ResponseModel (tuple / plain results); same outcome as a denied ResponseModel.
                case PermissionDeniedException:
                    response.StatusCode = (int)HttpStatusCode.Forbidden;
                    response.Titel = "Forbidden";
                    break;

                default:
                    response.StatusCode = (int)HttpStatusCode.InternalServerError;
                    response.Titel = "Internal Server Error";
                    break;
            }

            httpContext.Response.StatusCode = response.StatusCode;
            await httpContext.Response.WriteAsJsonAsync(response, cancellationToken);

            return true;
        }
    }
}

