using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.MultiTenancy;
using SolutionOne_DataAccessLayer.MultiTenancy;
using System.Net;

namespace SolutionOneWebPortal_API.Controllers.Common
{
    /// <summary>
    /// Tenant catalogue lookup for the legacy SolutionOneWeb payroll app.
    ///
    /// Legacy stores its product key in Web.config and calls Resolve to learn WHICH database it
    /// should use. It deliberately gets identity only - never a connection string - for two
    /// reasons: SQL credentials never cross the network, and the two applications connect to the
    /// same customer database with their own separate logins (legacy builds the connection from
    /// its clientConnectionTemplate, this API from MultiTenancy:ClientConnectionTemplate).
    ///
    /// It also means legacy no longer needs any rights on HR_Master, which removes the
    /// "Cannot open database 'HR_Master' requested by the login" failure its own
    /// DbConnectionFactory documents.
    /// </summary>
    [AllowAnonymous]
    [Route("api/[controller]")]
    [ApiController]
    public class TenantController : ControllerBase
    {
        private readonly ITenantRegistry _registry;
        private readonly ITenantContext _tenantContext;
        private readonly ILogger<TenantController> _logger;

        public TenantController(ITenantRegistry registry, ITenantContext tenantContext, ILogger<TenantController> logger)
        {
            _registry = registry;
            _tenantContext = tenantContext;
            _logger = logger;
        }

        /// <summary>
        /// Exchanges a product key for the tenant's identity.
        ///
        /// Anonymous by design: presenting a valid key is itself the proof of which tenant you are,
        /// and the response contains nothing a holder of that key does not already know. It is rate
        /// limited because it is otherwise an oracle for enumerating keys.
        /// </summary>
        [HttpPost]
        [Route("Resolve")]
        [EnableRateLimiting("tenant-resolve")]
        public async Task<IActionResult> Resolve([FromBody] TenantResolveRequest request)
        {
            var responseModel = new ResponseModel();

            if (_tenantContext.IsSingleTenantMode)
            {
                // A single-database deployment has no catalogue. Say so plainly so the legacy app
                // can fall back to its own Web.config rather than retrying a lookup that can never
                // succeed.
                responseModel.IsSuccess = false;
                responseModel.Status = HttpStatusCode.NotFound;
                responseModel.Message = "Multi-tenancy is not enabled on this server.";
                return NotFound(responseModel);
            }

            TenantInfo? tenant = await _registry.ResolveByProductKeyAsync(request?.ProductKey, HttpContext.RequestAborted);

            if (tenant is null)
            {
                // The key is never logged - it is a credential.
                _logger.LogWarning("Tenant resolve refused: product key not found in the catalogue.");
                responseModel.IsSuccess = false;
                responseModel.Status = HttpStatusCode.Unauthorized;
                responseModel.Message = "Invalid product key.";
                return Unauthorized(responseModel);
            }

            if (!tenant.IsActive)
            {
                _logger.LogWarning("Tenant resolve refused: {ClientCode} is not active.", tenant.ClientCode);
                responseModel.IsSuccess = false;
                responseModel.Status = HttpStatusCode.Forbidden;
                responseModel.Message = "This subscription is not active.";
                return StatusCode((int)HttpStatusCode.Forbidden, responseModel);
            }

            responseModel.IsSuccess = true;
            responseModel.Status = HttpStatusCode.OK;
            responseModel.Message = "Tenant resolved.";
            responseModel.Data = new TenantResolveResponse
            {
                ClientId = tenant.ClientId,
                ClientCode = tenant.ClientCode,
                DatabaseName = tenant.DatabaseName,
                IsActive = tenant.IsActive,
                SchemaVersion = tenant.SchemaVersion
            };

            return Ok(responseModel);
        }
    }

    public sealed class TenantResolveRequest
    {
        public string? ProductKey { get; set; }
    }

    public sealed class TenantResolveResponse
    {
        public int ClientId { get; set; }
        public string ClientCode { get; set; } = string.Empty;

        /// <summary>Initial Catalog the caller should connect to, using its own credentials.</summary>
        public string DatabaseName { get; set; } = string.Empty;

        public bool IsActive { get; set; }

        /// <summary>
        /// Null until the migration consolidation lands. Callers must treat null as "unknown" and
        /// not as "behind", or every tenant would look out of date on day one.
        /// </summary>
        public int? SchemaVersion { get; set; }
    }
}
