#region External Login (no password validation)
[HttpPost]
[Route("ExternalLogin")]
public async Task<IActionResult> ExternalLogin([FromBody] ExternalLoginRequest request)
{
    ResponseModel responseModel = new ResponseModel();

    try
    {
        if (request.UserId <= 0)
        {
            responseModel.IsSuccess = false;
            responseModel.Status = HttpStatusCode.BadRequest;
            responseModel.Message = "A valid UserId must be provided.";
            return BadRequest(responseModel);
        }

        var (response, data, permissions, menus) = await _service.ExternalLogin(request.UserId);
        if (!response.IsSuccess || data == null)
        {
            return Unauthorized(response);
        }

        string token = await GenerateTokenAsync(data);

        HttpContext.Session.SetInt32("UserId", (int)data.UserMasterId);
        HttpContext.Session.SetString("UserName", data.UserName);
        HttpContext.Session.SetString("UserRole", data.Role ?? "");
        HttpContext.Session.SetInt32("UserEmpId", (int)(data.EmployeeMasterId ?? 0));
        HttpContext.Session.SetString("CompanyId", data.CompanyMasterId.ToString() ?? "-1");

