# --- helper, placed just before the JWT region ---
old_region = """        #region JWT Authentication"""
new_region = """        #region Tenant Refusal
        /// <summary>
        /// Turns a failed tenant bind into the response the caller should get, or null when the
        /// request may continue. Kept in one place so Login and ExternalLogin cannot drift apart on
        /// what a suspended subscription or an unknown key looks like.
        ///
        /// "Invalid product key" is deliberately not distinguished from "no such customer": telling
        /// an anonymous caller which keys exist would make this an enumeration oracle.
        /// </summary>
        private IActionResult? RefuseTenant(TenantBindResult bind, ResponseModel responseModel)
        {
            switch (bind.Status)
            {
                case TenantBindStatus.Missing:
                    _logger.LogWarning("Login refused: no product key supplied.");
                    responseModel.IsSuccess = false;
                    responseModel.Status = HttpStatusCode.BadRequest;
                    responseModel.Message = "A product key is required to sign in.";
                    return BadRequest(responseModel);

                case TenantBindStatus.Suspended:
                    _logger.LogWarning("Login refused: tenant {ClientCode} is not active.", bind.Tenant?.ClientCode);
                    responseModel.IsSuccess = false;
                    responseModel.Status = HttpStatusCode.Forbidden;
                    responseModel.Message = "This subscription is not active. Please contact your administrator.";
                    return StatusCode((int)HttpStatusCode.Forbidden, responseModel);

                case TenantBindStatus.NotFound:
                    // The key itself is never logged.
                    _logger.LogWarning("Login refused: product key not found in the catalogue.");
                    responseModel.IsSuccess = false;
                    responseModel.Status = HttpStatusCode.Unauthorized;
                    responseModel.Message = "Invalid product key.";
                    return Unauthorized(responseModel);

                default:
                    return null;
            }
        }
        #endregion

        #region JWT Authentication"""
