        // tooling - dotnet ef / scaffolding - which constructs the context with no options at all.
        if (optionsBuilder.IsConfigured)
        {
            return;
        }

        if (_configuration == null)
        {
            throw new InvalidOperationException(
                "HrmsystemContext was created without configured options. At runtime it must be resolved from DI so the request's tenant connection is used.");
        }

        var connectionString = _configuration.GetConnectionString("WebPortalConnectionString");
        string pass = "Gsspl@2024Gsspl@";

        if (connectionString == null) throw new InvalidOperationException("Connection string not provided");

        AESEncryption aes = new AESEncryption(_configuration);
        var decrypt = aes.Decrypt(connectionString, pass);
        optionsBuilder.UseSqlServer(decrypt);
