constructor(
  private authService: AuthService,
  private router: Router,
  private apiService: ApiService,
  private toasterservice: ToastService,
  private route: ActivatedRoute,
  private _fb: FormBuilder,
) {
  this.logindata = this._fb.group({
    userName: [null, [Validators.required]],
    passwordHash: [null, [Validators.required]],
  });
}

async ngOnInit(): Promise<void> {
  this.route.queryParams.subscribe(async (params) => {
    const token = params['token'];

    if (token) {
      const success = await this.authService.handleSSOToken(token);

      if (success) {
        window.history.replaceState({}, document.title, window.location.pathname);
        this.router.navigate(['/dashboard']);
      } else {
        this.toasterservice.error('Invalid or expired SSO token.');
        this.router.navigate(['/login']);
      }
    }
  });
}

onSubmit() {
  this.showLoader = true;

  if (this.logindata.invalid) {
    this.showLoader = false;
    this.toasterservice.error('Please fill all required fields');
    return;
  }

  const payload = {
    userName: this.logindata.value.userName,
    passwordHash: this.logindata.value.passwordHash,
  };

  this.apiService.post(`/api/Login/LoginAuthentication`, payload).subscribe({
    next: (data: any) => {
      this.showLoader = false;
      this.submitted = false;

      if (data?.isSuccess === false || data?.IsSuccess === false) {
        this.toasterservice.error(data?.message || data?.Message || 'Login failed.');
        return;
      }

      const body = data ?? {};
      const loginPayload =
        body?.data && typeof body.data === 'object'
          ? body.data
          : body?.Data && typeof body.Data === 'object'
            ? body.Data
            : body;

      if (!this.authService.saveSession(loginPayload)) {
        this.toasterservice.error('Login failed. Token not received.');
        return;
      }

      this.router.navigate(['/my-dashboard']);
      this.toasterservice.success('Login successful.');
    },
    error: (err: HttpErrorResponse) => {
      this.showLoader = false;
      const body = err?.error as Record<string, unknown> | null | undefined;
      const message =
        (typeof body?.['message'] === 'string' && body['message']) ||
        (typeof body?.['Message'] === 'string' && body['Message']) ||
        'Invalid username or password.';
      this.toasterservice.error(message as string);
    },

