      productKey: [LoginComponent.rememberedProductKey()],
    });"""
assert old_form in s
s = s.replace(old_form, new_form, 1)

old_payload = """    const payload = {
      userName: this.logindata.value.userName,
      passwordHash: this.logindata.value.passwordHash,
    };"""
new_payload = """    const productKey = (this.logindata.value.productKey ?? '').trim();

    const payload = {
      userName: this.logindata.value.userName,
      passwordHash: this.logindata.value.passwordHash,
      productKey,
    };"""
assert old_payload in s
s = s.replace(old_payload, new_payload, 1)

old_success = """        this.router.navigate(['/my-dashboard']);
        this.toasterservice.success('Login successful.');"""
new_success = """        // Remembered only after the server accepted it, so a mistyped key is not kept.
        // It is a tenant selector, not a secret from the person typing it - the password is what
        // authenticates. The token, not this, is what later requests are trusted on.
        LoginComponent.rememberProductKey(productKey);

        this.router.navigate(['/my-dashboard']);
        this.toasterservice.success('Login successful.');"""
assert old_success in s
s = s.replace(old_success, new_success, 1)

