idx = s.rstrip().rfind('}')
helpers = """
  private static readonly PRODUCT_KEY_STORAGE = 'hrms.productKey';

  /** Blank when storage is unavailable (private window, blocked site data) - never throws. */
  private static rememberedProductKey(): string | null {
    try {
      return localStorage.getItem(LoginComponent.PRODUCT_KEY_STORAGE);
    } catch {
      return null;
    }
  }

  private static rememberProductKey(productKey: string): void {
    try {
      if (productKey) {
        localStorage.setItem(LoginComponent.PRODUCT_KEY_STORAGE, productKey);
      }
    } catch {
      // Storage unavailable: the user retypes the key next time, which is not worth failing a
      // successful login over.
    }
  }
"""
