using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SolutionOne_BusinessLogicLayer.Services.HR.Interface;
using SolutionOne_Core.HRModels.ResumeParsing;

namespace SolutionOne_BusinessLogicLayer.Services.HR.Implementation;

/// <summary>
/// Bounded concurrency via a fixed number of long-running consumer loops over the shared queue,
/// rather than a semaphore - simplest to reason about and tune (just change Concurrency).
/// </summary>
public class ResumeProcessingWorker(
    IResumeProcessingQueue queue,
    IServiceScopeFactory scopeFactory,
    IOptions<ResumeParsingSettings> options,
    ILogger<ResumeProcessingWorker> logger
    ) : BackgroundService
{
    private readonly int _concurrency = Math.Max(1, options.Value.Concurrency);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var consumers = Enumerable.Range(0, _concurrency)
            .Select(_ => ConsumeAsync(stoppingToken));

        await Task.WhenAll(consumers);
    }

    private async Task ConsumeAsync(CancellationToken stoppingToken)
    {
        await foreach (var job in queue.Reader.ReadAllAsync(stoppingToken))
        {
            using var scope = scopeFactory.CreateScope();
            var orchestrator = scope.ServiceProvider.GetRequiredService<IResumeBatchOrchestrator>();

            try
            {
                // The orchestrator already catches and records per-file failures via
                // IResumeBatchStore; this catch is a last-resort net so a bug in that handling
                // itself can never take down the consumer loop and stall the rest of the batch.
                await orchestrator.ProcessAsync(job, stoppingToken);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Unhandled error processing resume file {FileName} in batch {BatchId}.", job.FileName, job.BatchId);
            }
        }
    }
}
