using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace SolutionOne_BusinessLogicLayer.Middleware.Common.StartupTasks;

/// <summary>
/// Runs every registered <see cref="StartupTaskDelegate"/> once, at app boot, in a fresh DI scope.
/// One shared hosted service for all boot-time work - adding a new task is a one-line
/// AddStartupTask(...) call in the owning module's DI extension, not a new IHostedService class.
/// </summary>
public class StartupTaskRunnerHostedService : IHostedService
{
    private readonly IEnumerable<StartupTaskDelegate> _tasks; // Registering the tasks
    private readonly IServiceProvider _provider;
    private readonly ILogger<StartupTaskRunnerHostedService> _logger;

    public StartupTaskRunnerHostedService(
        IEnumerable<StartupTaskDelegate> tasks,
        IServiceProvider provider,
        ILogger<StartupTaskRunnerHostedService> logger)
    {
        _tasks = tasks;
        _provider = provider;
        _logger = logger;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        using var scope = _provider.CreateScope();
        foreach (var task in _tasks)
        {
            try
            {
                await task(scope.ServiceProvider, cancellationToken);
            }
            catch (Exception ex)
            {
                // A failing startup task must never block the app from serving traffic.
                _logger.LogError(ex, "Startup task failed");
            }
        }
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

