namespace SolutionOne_BusinessLogicLayer.Services.HR.Models;

/// <summary>
/// Queue payload for one resume file. Content is buffered into memory up-front because the
/// IFormFile stream backing the original upload is only valid for the lifetime of the HTTP
/// request, which ends as soon as the batch endpoint returns.
/// </summary>
public class ResumeProcessingJob
{
    public Guid BatchId { get; set; }
    public Guid FileId { get; set; }
    public string FileName { get; set; } = string.Empty;
    public byte[] Content { get; set; } = Array.Empty<byte>();

    /// <summary>HrPostedJob.Id. Null for the manual create-candidate-then-attach flow; when set,
    /// ResumeBatchOrchestrator upserts the parsed result straight onto a candidate row for this
    /// posted job (see IResumeCandidateUpsertService) instead of waiting for a manual attach.</summary>
    public long? JobId { get; set; }

    /// <summary>Required whenever JobId is set (enforced in ResumeParsingController) - applied to
    /// every candidate this batch auto-creates for that posted job.</summary>
    public string? PlatformSource { get; set; }

    /// <summary>When true, parse and score against JobId's requisition but create no candidate
    /// record - lets a caller preview matches before committing. Match is still computed and
    /// surfaced via the batch status/stream regardless of this flag; it only gates persistence.</summary>
    public bool MatchOnly { get; set; }
}
