namespace SolutionOne_BusinessLogicLayer.Services.HR.Implementation;

/// <summary>
/// Sweeps out batch status + staged-but-unattached resume files older than
/// ResumeParsingSettings.BatchExpiryMinutes, on a fixed interval. Nothing about resume parsing
/// is durable yet (see backend.md#state--persistence), so this is a hard expiry regardless of
/// whether the batch finished processing or the user ever came back to confirm a candidate save.
/// </summary>
public class ResumeBatchCleanupWorker(
    IResumeBatchStore batchStore,
    IOptions<ResumeParsingSettings> options,
    ILogger<ResumeBatchCleanupWorker> logger
    ) : BackgroundService
{
    private readonly TimeSpan _batchExpiry = TimeSpan.FromMinutes(Math.Max(1, options.Value.BatchExpiryMinutes));
    private readonly TimeSpan _sweepInterval = TimeSpan.FromMinutes(Math.Max(1, options.Value.CleanupIntervalMinutes));

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(_sweepInterval);

        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            RunSweep();
        }
    }

    private void RunSweep()
    {
        var staleFilePaths = batchStore.RemoveExpiredBatches(_batchExpiry);

        foreach (var path in staleFilePaths)
        {
            try
            {
                if (File.Exists(path))
                    File.Delete(path);
            }
            catch (Exception ex)
            {
                logger.LogWarning(ex, "Failed to delete expired staged resume file {Path}.", path);
            }
        }

