using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using SolutionOne_Core.MultiTenancy;

namespace SolutionOne_DataAccessLayer.MultiTenancy
{
    /// <summary>
    /// Runs work in a DI scope that has a tenant bound to it.
    ///
    /// Background work has no HTTP request, so TenantResolutionMiddleware never runs for it and
    /// nothing binds a tenant - every connection attempt would throw. Before multi-tenancy that was
    /// invisible because there was only ever one database; now a hosted service must say which
    /// tenant it means, every time.
    /// </summary>
    public interface ITenantScopeRunner
    {
        /// <summary>
        /// Runs <paramref name="work"/> once per active tenant, each in its own scope. In
        /// single-tenant mode it runs exactly once with no tenant bound, which is the old behaviour.
        /// One tenant failing does not stop the others.
        /// </summary>
        Task RunForEachActiveTenantAsync(
            Func<IServiceProvider, TenantInfo?, CancellationToken, Task> work,
            CancellationToken cancellationToken = default);

        /// <summary>
        /// Runs <paramref name="work"/> in a scope bound to one specific tenant - for queued work
        /// that was stamped with its tenant when it was enqueued by a request.
        /// </summary>
        Task RunForTenantAsync(
            int clientId,
            Func<IServiceProvider, CancellationToken, Task> work,
            CancellationToken cancellationToken = default);
    }

    public sealed class TenantScopeRunner : ITenantScopeRunner
    {
        private readonly IServiceScopeFactory _scopeFactory;
        private readonly ITenantRegistry _registry;
        private readonly TenantRuntimeConfig _config;
        private readonly ILogger<TenantScopeRunner> _logger;

        public TenantScopeRunner(
            IServiceScopeFactory scopeFactory,
            ITenantRegistry registry,
            TenantRuntimeConfig config,
            ILogger<TenantScopeRunner> logger)
        {
            _scopeFactory = scopeFactory;
            _registry = registry;
            _config = config;
            _logger = logger;
        }

        public async Task RunForEachActiveTenantAsync(
            Func<IServiceProvider, TenantInfo?, CancellationToken, Task> work,
            CancellationToken cancellationToken = default)
        {
            if (!_config.Enabled)
            {
                using var scope = _scopeFactory.CreateScope();
                await work(scope.ServiceProvider, null, cancellationToken);
                return;
            }

            IReadOnlyList<TenantInfo> tenants = await _registry.GetActiveTenantsAsync(cancellationToken);

            foreach (TenantInfo tenant in tenants)
            {
                if (cancellationToken.IsCancellationRequested)
                {
                    return;
                }

                try
                {
                    using var scope = CreateBoundScope(tenant);
                    await work(scope.ServiceProvider, tenant, cancellationToken);
                }
                catch (Exception ex)
                {
                    // Sequential and isolated on purpose: one customer's bad data or unreachable
                    // database must not stop the same job running for everyone else, and running
                    // every tenant at once would multiply the load on a shared cluster.
                    _logger.LogError(ex, "Background work failed for tenant {ClientCode} ({ClientId}).",
                        tenant.ClientCode, tenant.ClientId);
                }
            }
        }

        public async Task RunForTenantAsync(
            int clientId,
            Func<IServiceProvider, CancellationToken, Task> work,
            CancellationToken cancellationToken = default)
        {
            if (!_config.Enabled)
            {
                using var scope = _scopeFactory.CreateScope();
                await work(scope.ServiceProvider, cancellationToken);
                return;
            }

            TenantInfo? tenant = await _registry.ResolveByClientIdAsync(clientId, cancellationToken);

            if (tenant is null || !tenant.IsActive)
            {
                // The work was queued while the tenant was live and is being run after it was
                // removed or suspended. Dropping it is correct - the alternative is writing to a
                // database the subscription no longer covers.
                _logger.LogWarning(
                    "Dropping queued work for tenant {ClientId}: it is no longer active in the catalogue.", clientId);
                return;
            }

            using var boundScope = CreateBoundScope(tenant);
            await work(boundScope.ServiceProvider, cancellationToken);
        }

        private IServiceScope CreateBoundScope(TenantInfo tenant)
        {
            IServiceScope scope = _scopeFactory.CreateScope();

            try
            {
                scope.ServiceProvider
                     .GetRequiredService<ITenantContextSetter>()
                     .SetTenant(tenant, _registry.BuildConnectionString(tenant));

                return scope;
            }
            catch
            {
                scope.Dispose();
                throw;
            }
        }
    }
}
