p = 'SolutionOne_Tests/RbacPermissionValidationTests.cs'
s = open(p).read()

s = s.replace(
"using SolutionOne_DataAccessLayer.Repositories.Common.Implementation;",
"using SolutionOne_Core.MultiTenancy;\nusing SolutionOne_DataAccessLayer.MultiTenancy;\nusing SolutionOne_DataAccessLayer.Repositories.Common.Implementation;", 1)

old = """			// 2. Initialize DapperContext to connect to the database
			DapperContext dapperContext;
			try
			{
				dapperContext = new DapperContext(config);
			}"""
new = """			// 2. Initialize DapperContext to connect to the database.
			// DapperContext now takes its connection from the request's tenant instead of reading
			// appsettings itself. This test is single-database, so it builds a TenantContext in
			// single-tenant mode - the same path a deployment with MultiTenancy:Enabled = false
			// takes - and hands it the decrypted WebPortalConnectionString.
			DapperContext dapperContext;
			try
			{
				var aes = new AESEncryption(config);
				var decrypted = aes.Decrypt(config.GetConnectionString("WebPortalConnectionString"), "Gsspl@2024Gsspl@");

				var tenantContext = new TenantContext(new TenantRuntimeConfig
				{
					Enabled = false,
					DefaultConnectionString = decrypted
				});

				dapperContext = new DapperContext(tenantContext);
			}"""
assert old in s
s = s.replace(old, new, 1)
open(p,'w').write(s)
print("patched test")
PY
