        /// registered, so nothing can inject it and skip the guard.
        /// </summary>
        public static IServiceCollection AddPermissionGuarded<TService, TImpl>(this IServiceCollection services)
            where TService : class
            where TImpl : class, TService
        {
            services.AddScoped<TService>(sp => PermissionGuardProxy<TService>.Create(
                ActivatorUtilities.CreateInstance<TImpl>(sp),
                sp.GetRequiredService<IPermissionChecker>(),
                sp.GetRequiredService<ILoggerFactory>().CreateLogger($"PermissionGuard.{typeof(TService).Name}")));
            return services;
        }
    }
}

