        [HttpPost]
        [Route("Verify")]
        [EnableRateLimiting("tenant-resolve")]
        public async Task<IActionResult> Verify([FromBody] TenantResolveRequest request)
        {
            var responseModel = new ResponseModel();

            // A single-database deployment has no product keys. Reported as success with
            // RequiresProductKey = false so the login screen can hide the whole flow instead of
            // showing an option that cannot work.
            if (_tenantContext.IsSingleTenantMode)
