    font-family: Calibri, sans-serif;
}

.login-page {
    display: flex;
    flex-direction: column;
    /* dvh tracks the viewport as mobile browsers show and hide their URL bar; vh does not, which
       is why 100vh content sits partly under the address bar on iOS. vh first as the fallback. */
    min-height: 100vh;
    min-height: 100dvh;
}

/* ----------------------------------------------------------------- support bar */

.support-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 4px 16px;
    padding: 8px 16px;
