}

.brand-bg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
}

.brand-content {
    position: relative;
    z-index: 1;
    text-align: center;
    padding: 0 24px;
}

.login-panel {
    flex: 1 1 34%;
