    align-items: center;
    justify-content: center;
    background-color: #fff;
    padding: 24px 16px;
}

.login-box {
    width: 100%;
    max-width: 380px;
    padding: 24px;
    border-radius: 8px;
    background-color: #fffcfc;
    box-shadow: 0 .5rem 1rem rgba(0, 0, 0, .15);
}

.logo-wrap {
    text-align: center;
    margin-bottom: 16px;
}

/* Was a fixed 120px box with a 50%-width image - on a short screen that was wasted height, and the
   image could overflow its container. Caps by height instead so it scales with the viewport. */
.logo-wrap img {
    max-width: 60%;
    max-height: 90px;
    height: auto;
}

/* ----------------------------------------------------------------- type */

.ERPText {
    color: rgb(253 145 0);
    font-size: clamp(24px, 3.5vw, 35px);
    font-weight: 600;
    line-height: 1.2;
}

.slogan {
    font-size: clamp(15px, 1.8vw, 20px);
    margin-top: 8px;
}

.loginText {
    text-align: center;
    margin-bottom: 6px;
    font-size: 16px;
    font-weight: 500;
}

.step-hint {
    text-align: center;
    font-size: 13px;
    color: #6c757d;
    margin: 0 0 12px;
}

/* ----------------------------------------------------------------- fields */

/* 16px is not cosmetic: iOS Safari auto-zooms the page on focus for any input under 16px, which
   on the old 14px fields left the user zoomed in and scrolled sideways after tapping Password. */
.formfield {
    width: 100%;
    padding: 10px 14px;
    margin: 8px 0;
    border: 1px solid #ccc;
    border-radius: 5px;
    font-size: 16px;
    font-family: Calibri, sans-serif;
}

.formfield:focus {
    outline: none;
    border-color: #3949ab;
    box-shadow: 0 0 0 2px rgba(57, 73, 171, .15);
}

/* Keys are read off a sheet of paper and typed in groups - monospace with a little tracking makes
   a mistyped character findable. */
.key-field {
    font-family: 'Courier New', monospace;
    letter-spacing: .5px;
    text-transform: uppercase;
}

.forgotpassworddiv {
    text-align: end;
    margin-bottom: 12px;
}

.forgotpassword {
    font-size: 14px;
    color: #0056b3;
    font-weight: 500;
    text-decoration: none;
}

/* ----------------------------------------------------------------- actions */

.btn-primary-action {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    /* 44px is the minimum comfortable tap target; the old 6px padding gave about 30px. */
    min-height: 44px;
    padding: 8px 12px;
    margin-top: 8px;
    background-color: #3949ab;
