.btn-primary-action:hover:not(:disabled) {
    background-color: #2f3d91;
}

.btn-primary-action:disabled {
    opacity: .7;
    cursor: default;
}

.mode-switch {
    text-align: center;
    margin-top: 14px;
}

.mode-switch a {
    font-size: 14px;
    color: #3949ab;
    font-weight: 600;
    text-decoration: none;
    /* Padding rather than margin so the tap target is bigger than the text itself. */
    display: inline-block;
    padding: 6px 4px;
}

.mode-switch a:hover {
    text-decoration: underline;
}

.tenant-badge {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 12px;
    margin-bottom: 12px;
    border: 1px solid #c3e6cb;
    border-radius: 5px;
    background-color: #eaf7ed;
    color: #1d6b32;
    font-size: 15px;
    font-weight: 600;
}

.tenant-badge span {
    flex: 1 1 auto;
    /* A long client code must not push the Change link off the card. */
    overflow-wrap: anywhere;
}

.tenant-badge a {
    flex: 0 0 auto;
    font-size: 13px;
    font-weight: 600;
    color: #0056b3;
    text-decoration: underline;
    padding: 2px 4px;
}

.copyright-wrap {
    text-align: center;
    margin-top: 16px;
}

.copyright {
    font-size: 13px;
    color: gray;
}

/* ----------------------------------------------------------------- breakpoints */

@media (max-width: 991.98px) {

    /* The branding panel is decoration; on a phone it would push the form below the fold. */
    .login-brand {
        display: none;
    }

    .login-panel {
        flex: 1 1 100%;
        padding: 16px;
        /* Vertically centred while it fits, top-aligned once the keyboard shrinks the viewport,
           so the fields stay reachable instead of being pinned to a centre that no longer exists. */
        align-items: flex-start;
    }

    .login-box {
        max-width: 420px;
        margin: 0 auto;
        box-shadow: none;
        background-color: transparent;
        padding: 16px 8px;
    }
}

@media (max-width: 575.98px) {
    .support-bar {
        justify-content: center;
        text-align: center;
        font-size: 13px;
        padding: 8px 12px;
    }

    .support-phones {
        justify-content: center;
    }

    .logo-wrap img {
        max-width: 55%;
        max-height: 70px;
    }

    .loginText {
        font-size: 15px;
    }

    /* The placeholder is a full 34-character key; shrink it just enough to fit a 320px screen
       without shrinking what the user types. */
    .key-field::placeholder {
        font-size: 13px;
    }
}

/* Landscape phone: almost no vertical room, so drop the decorative spacing. */
@media (max-height: 520px) and (max-width: 991.98px) {
    .logo-wrap {
        margin-bottom: 8px;
    }

    .logo-wrap img {
        max-height: 48px;
    }

    .copyright-wrap {
        margin-top: 10px;
    }
}
