   * 'standard'  - employee code + password against this server's own database.
   * 'tenant'    - the client enters their product key FIRST, we confirm which company it belongs
   *               to, and only then ask for credentials. Keeping it a separate mode means the
   *               ordinary login screen is not cluttered with a field most users never need.
   */
  mode: 'standard' | 'tenant' = 'standard';

  /** Within 'tenant' mode: collect the key, then the credentials. */
  tenantStep: 'key' | 'credentials' = 'key';

  /** Company the verified key belongs to - shown so the user can see they typed the right key. */
  verifiedClientCode: string | null = null;

  /** Key-step spinner, separate from showLoader so the two buttons never both spin. */
  verifying = false;

