        private const string ConnectionStringEncryptionKey = "Gsspl@2024Gsspl@";

        public DatabaseProvisioningService(
            SubscriptionPortalDbContext context,
            ITenantDatabaseRepository tenantDatabaseRepository,
            IOptions<HrmsProvisioningSettings> hrmsSettings,
            ILogger<DatabaseProvisioningService> logger)
        {
            _context = context;
            _tenantDatabaseRepository = tenantDatabaseRepository;
            _hrmsSettings = hrmsSettings.Value;
