        {
            if (!_hrmsSettings.IsConfigured)
            {
                return new ProvisioningResult(false, null, null,
                    "HrmsProvisioning is not configured (TemplateBackupPath/DataFileDirectory missing in appsettings.json).");
            }

            var masterConnectionString = BuildConnectionString("master");

            // Only ever returns the LIVE row - a retired database keeps its own row and is left
            // alone here, so this is never mistaken for "already provisioned".
            var existing = await _tenantDatabaseRepository.GetByTenantAndProductAsync(tenantId, productCode);
            if (existing is { Status: TenantDatabaseStatus.Active })
            {
                return new ProvisioningResult(false, null, null, "A database is already provisioned for this tenant/product.");
            }

            var databaseName = await ResolveAvailableDatabaseNameAsync(masterConnectionString, productCode, tenantId, tenantSubdomain);

            try
            {
                await RestoreTemplateAsync(masterConnectionString, databaseName);

                var tenantConnectionString = BuildConnectionString(databaseName);
                var adminCode = await SeedAdminUserAsync(tenantConnectionString, companyName, adminEmail, adminName, contactNumber, adminPassword);

                var encryptedConnectionString = AesCrypto.Encrypt(tenantConnectionString, ConnectionStringEncryptionKey);
                var serverName = new SqlConnectionStringBuilder(masterConnectionString).DataSource;

                if (existing is null)
