                    existing.DatabaseName = databaseName;
                    existing.EncryptedConnectionString = encryptedConnectionString;
                    existing.Status = TenantDatabaseStatus.Active;
                    existing.ProvisionedDate = DateTime.UtcNow;
                    existing.FailureReason = null;
                    await _tenantDatabaseRepository.SaveChangesAsync();
                }

                return new ProvisioningResult(true, databaseName, adminCode, null);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Provisioning failed for TenantId {TenantId}, Product {ProductCode}, Database {DatabaseName}. Attempting cleanup.",
