        ///
        /// <para>ProductCode is part of the name because one tenant can run several products, and
        /// the numeric "_2/_3/..." tail is still needed on top of that: when a customer subscribes
        /// and chooses to start clean, the demo database is retired but deliberately LEFT on the
        /// server, so the replacement cannot reuse its name. RESTORE DATABASE over an existing
        /// database would have overwritten exactly the data retiring it was meant to preserve.</para>
        ///
        /// <para>Names stay well inside SQL Server's 128-character sysname limit: the subdomain
        /// part is capped at 40 characters, which only ever shortens the readable label, never the
        /// unique TenantId/suffix part.</para>
        /// </summary>
        private static async Task<string> ResolveAvailableDatabaseNameAsync(string masterConnectionString, string productCode, long tenantId, string subdomain)
