            await connection.OpenAsync();

            // Bounded so a misconfiguration can never spin here; 50 generations of one tenant's
            // database for one product is far past anything legitimate.
            for (var suffix = 1; suffix <= 50; suffix++)
            {
                var candidate = suffix == 1 ? baseName : $"{baseName}_{suffix}";

                await using var command = new SqlCommand(
                    "SELECT COUNT(1) FROM sys.databases WHERE name = @name", connection);
                command.Parameters.AddWithValue("@name", candidate);

                var taken = Convert.ToInt32(await command.ExecuteScalarAsync()) > 0;
                if (!taken)
