namespace SubscriptionPortal.Core.CommonModels
{
    public class HrmsProvisioningSettings
    {
        /// <summary>Full path to the HRMS template .bak file, as seen by the SQL Server process
        /// (not necessarily this app's own machine) - the RESTORE statement runs on the server.</summary>
        public string TemplateBackupPath { get; set; } = string.Empty;

        /// <summary>Directory on the SQL Server machine where new tenant .mdf/.ldf files are
        /// created. Must be a real, writable path on that server.</summary>
        public string DataFileDirectory { get; set; } = string.Empty;

        /// <summary>Must match HRMS's own "PasswordEncryption:Key" exactly - both sides read/write
        /// the same HR_UserMaster.PasswordHash column, see HRMS's PasswordEncryptionSettings.cs.</summary>
        public string HrmsPasswordEncryptionKey { get; set; } = string.Empty;

        /// <summary>The HRMS application's own sign-in page - linked directly from the
        /// "workspace ready" email so the admin can click straight through to log in.</summary>
        public string HrmsLoginUrl { get; set; } = string.Empty;

        public bool IsConfigured =>
            !string.IsNullOrWhiteSpace(TemplateBackupPath) && !TemplateBackupPath.StartsWith("REPLACE_") &&
            !string.IsNullOrWhiteSpace(DataFileDirectory) && !DataFileDirectory.StartsWith("REPLACE_");
    }
}
