namespace SubscriptionPortal.Core.CommonModels
{
    public class HrmsProvisioningSettings
    {
        /// <summary>
        /// Directory holding the generated tenant template scripts (01_schema.sql,
        /// 02_master_data.sql, 03_baseline_stamp.sql). Unlike the .bak this replaced, these are
        /// read by THIS application and sent over the connection, so the path is on the API host -
        /// the SQL Server needs no filesystem access at all. That is what makes the approach work
        /// against a container or a managed cloud instance.
        ///
        /// Left blank, it defaults to SqlScripts/HrmsTemplate/out beside the running binary, where
        /// the DataAccessLayer csproj copies them.
        /// </summary>
        public string TemplateScriptsPath { get; set; } = string.Empty;

        /// <summary>
        /// Collation for new tenant databases. MUST be set explicitly and MUST match the database
        /// the template was generated from: the reference database is Latin1_General_CI_AI
        /// (accent-INsensitive) while a typical server default is SQL_Latin1_General_CP1_CI_AS
        /// (accent-sensitive). Inheriting the server default silently changes string matching
        /// across the whole HRMS, and makes any cross-database join fail with
        /// "Cannot resolve collation conflict".
        /// </summary>
        public string TemplateCollation { get; set; } = "Latin1_General_CI_AI";

        /// <summary>
        /// Compatibility level for new tenant databases. The reference database runs at 110
        /// (SQL Server 2012) and the HRMS query layer is written for it, so a database created on a
        /// newer server - which would otherwise default to that server's native level - is pinned
        /// back to match. Set to 0 to leave the server default alone.
        /// </summary>
        public int TemplateCompatibilityLevel { get; set; } = 110;

        /// <summary>
        /// Optional. Directory ON THE SQL SERVER MACHINE for new .mdf/.ldf files. Leave blank -
        /// the normal case - and SQL Server puts them in its own default data path, which is what
        /// you want in a container or on a managed instance where this app cannot know the layout.
        /// </summary>
        public string DataFileDirectory { get; set; } = string.Empty;

        /// <summary>Must match HRMS's own "PasswordEncryption:Key" exactly - both sides read/write
        /// the same HR_UserMaster.PasswordHash column, see HRMS's PasswordEncryptionSettings.cs.</summary>
        public string HrmsPasswordEncryptionKey { get; set; } = string.Empty;

        /// <summary>The HRMS application's own sign-in page - linked directly from the
        /// "workspace ready" email so the admin can click straight through to log in.</summary>
        public string HrmsLoginUrl { get; set; } = string.Empty;

        /// <summary>
        /// Only the collation is strictly required now. The scripts path has a working default and
        /// DataFileDirectory is optional, so a fresh install provisions without being told about
        /// any server-side path - which was the main thing making the old .bak setup fragile.
        /// </summary>
        public bool IsConfigured =>
            !string.IsNullOrWhiteSpace(TemplateCollation) && !TemplateCollation.StartsWith("REPLACE_");
    }
}
