using System.Text.RegularExpressions;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;

namespace SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Implementation
{
    /// <summary>
    /// Executes a .sql file that uses GO as a batch separator.
    ///
    /// GO is a client directive, not T-SQL - SqlCommand rejects it outright - so the file has to be
    /// split before it is sent. It also genuinely matters for the template: CREATE PROCEDURE and
    /// CREATE VIEW must each be the first statement in their own batch, which is exactly what the
    /// GO lines in the generated schema are there to arrange.
    /// </summary>
    public static class SqlScriptRunner
    {
        /// <summary>
        /// Matches GO alone on a line, optionally followed by a comment. Anchored to line start and
        /// end so the word "GO" inside a string literal, an identifier or a comment body is not
        /// mistaken for a separator - the master-data script is full of template text that contains
        /// the word, and splitting on a bare "GO" would cut INSERT statements in half.
        /// Mirrors the regex HRMS's own DatabaseMigrationRunner uses, deliberately.
        /// </summary>
        private static readonly Regex GoBatchRegex =
            new(@"^\s*GO\s*(?:--.*)?$", RegexOptions.IgnoreCase | RegexOptions.Multiline | RegexOptions.Compiled);

        /// <summary>
        /// Runs every batch in <paramref name="scriptPath"/> against an already-open connection's
        /// database.
        ///
        /// Deliberately NOT wrapped in a transaction. The schema script is ~19,000 lines and
        /// hundreds of batches; one transaction over all of it escalates locks badly, and several
        /// DDL statements cannot share a batch anyway. Rollback is handled a level up by dropping
        /// the half-built database, which is both cheaper and complete.
        /// </summary>
        public static async Task<int> ExecuteFileAsync(
            string connectionString,
            string scriptPath,
            ILogger logger,
            int commandTimeoutSeconds = 300,
