        /// <summary>
        /// Creates an empty database with the collation and compatibility level the template was
        /// generated against.
        ///
        /// The collation is NOT left to the server default on purpose: the reference database is
        /// Latin1_General_CI_AI (accent-insensitive) and a typical server default is
        /// SQL_Latin1_General_CP1_CI_AS (accent-sensitive). Inheriting the default silently changes
        /// how every string comparison in the HRMS behaves and makes cross-database joins fail with
        /// "Cannot resolve collation conflict".
        /// </summary>
        private async Task CreateDatabaseAsync(string masterConnectionString, string databaseName)
        {
            await using var connection = new SqlConnection(masterConnectionString);
            await connection.OpenAsync();

            using (var existsCommand = new SqlCommand("SELECT DB_ID(@name)", connection))
            {
                existsCommand.Parameters.AddWithValue("@name", databaseName);
                var result = await existsCommand.ExecuteScalarAsync();
                if (result is not DBNull && result is not null)
                {
                    throw new InvalidOperationException($"Database '{databaseName}' already exists on the server.");
                }
            }

            // CREATE DATABASE takes no parameters for identifiers. databaseName comes from
            // ResolveAvailableDatabaseNameAsync, which strips everything but letters, digits and
            // underscore, and the collation is validated against sys.fn_helpcollations below - so
            // neither value can carry tenant input into the statement text.
            await GuardCollationAsync(connection, _hrmsSettings.TemplateCollation);

            var fileClause = string.Empty;
            if (!string.IsNullOrWhiteSpace(_hrmsSettings.DataFileDirectory))
            {
                // Only when explicitly configured. Left blank, SQL Server uses its own default data
                // path - which is the right behaviour in a container or on a managed instance,
                // where this process cannot know the server's directory layout.
                var dataDir = _hrmsSettings.DataFileDirectory.TrimEnd('\\', '/');
                var separator = dataDir.Contains('/') ? "/" : "\\";
                fileClause =
                    $" ON PRIMARY (NAME = [{databaseName}], FILENAME = '{dataDir}{separator}{databaseName}.mdf')" +
                    $" LOG ON (NAME = [{databaseName}_log], FILENAME = '{dataDir}{separator}{databaseName}_log.ldf')";
            }

            var createSql = $"CREATE DATABASE [{databaseName}]{fileClause} COLLATE {_hrmsSettings.TemplateCollation}";

            using (var createCommand = new SqlCommand(createSql, connection) { CommandTimeout = 300 })
            {
                await createCommand.ExecuteNonQueryAsync();
            }

            _logger.LogInformation("Created database {DatabaseName} with collation {Collation}.",
                databaseName, _hrmsSettings.TemplateCollation);

            if (_hrmsSettings.TemplateCompatibilityLevel > 0)
            {
                // Pinned rather than left at the server's native level: the HRMS query layer was
                // written against 110 and a newer level changes cardinality estimation and some
                // query semantics underneath it.
                var compatSql =
                    $"ALTER DATABASE [{databaseName}] SET COMPATIBILITY_LEVEL = {_hrmsSettings.TemplateCompatibilityLevel}";
                using var compatCommand = new SqlCommand(compatSql, connection) { CommandTimeout = 120 };
                await compatCommand.ExecuteNonQueryAsync();

                _logger.LogInformation("Set {DatabaseName} to compatibility level {Level}.",
                    databaseName, _hrmsSettings.TemplateCompatibilityLevel);
            }
        }

        /// <summary>
        /// Rejects a collation the server does not recognise, before it reaches a CREATE DATABASE
        /// statement that has to be built by string concatenation.
        /// </summary>
        private static async Task GuardCollationAsync(SqlConnection connection, string collation)
        {
            using var command = new SqlCommand(
                "SELECT COUNT(1) FROM sys.fn_helpcollations() WHERE name = @collation", connection);
            command.Parameters.AddWithValue("@collation", collation);

            var known = Convert.ToInt32(await command.ExecuteScalarAsync()) > 0;
            if (!known)
            {
                throw new InvalidOperationException(
                    $"HrmsProvisioning:TemplateCollation '{collation}' is not a collation this SQL Server recognises.");
            }
        }

        /// <summary>
        /// Applies the generated template to the new, empty database: schema, then master data,
        /// then the baseline migration stamp. Order matters and is not negotiable - master data
        /// has foreign keys into tables the schema creates, and the stamp has to land last so a
        /// failure part-way never leaves a database that claims to be fully migrated.
        /// </summary>
        private async Task ApplyTemplateScriptsAsync(string tenantConnectionString, string databaseName)
        {
            var scriptsPath = ResolveTemplateScriptsPath();

            // 03 is what stops the HRMS migration runner replaying all 224 baseline migrations
            // against a schema that already contains them, stopping at the first one that errors
            // and leaving the tenant silently part-migrated.
            string[] scripts = { "01_schema.sql", "02_master_data.sql", "03_baseline_stamp.sql" };

            foreach (var script in scripts)
            {
                var path = Path.Combine(scriptsPath, script);
                _logger.LogInformation("Applying {Script} to {DatabaseName}.", script, databaseName);
                await SqlScriptRunner.ExecuteFileAsync(tenantConnectionString, path, _logger);
            }
        }

        /// <summary>
        /// Configured path, or the copy that ships beside the binary. Resolved once per provision
        /// and checked here so a missing template fails with a path in the message rather than a
        /// FileNotFoundException three frames down.
        /// </summary>
        private string ResolveTemplateScriptsPath()
        {
            var configured = _hrmsSettings.TemplateScriptsPath;
            var path = string.IsNullOrWhiteSpace(configured)
                ? Path.Combine(AppContext.BaseDirectory, "SqlScripts", "HrmsTemplate", "out")
                : configured;

            if (!Directory.Exists(path))
            {
                throw new DirectoryNotFoundException(
                    $"Tenant template scripts directory not found: {path}. " +
                    "Set HrmsProvisioning:TemplateScriptsPath, or run generate-template.py to produce it.");
            }

            return path;
        }
