        /// <summary>
        /// Creates an empty database with the collation and compatibility level the template was
        /// generated against.
        ///
        /// The collation is NOT left to the server default on purpose: the reference database is
        /// Latin1_General_CI_AI (accent-insensitive) and a typical server default is
        /// SQL_Latin1_General_CP1_CI_AS (accent-sensitive). Inheriting the default silently changes
        /// how every string comparison in the HRMS behaves and makes cross-database joins fail with
        /// "Cannot resolve collation conflict".
        /// </summary>
        private async Task CreateDatabaseAsync(string masterConnectionString, string databaseName)
        {
            await using var connection = new SqlConnection(masterConnectionString);
            await connection.OpenAsync();

            using (var existsCommand = new SqlCommand("SELECT DB_ID(@name)", connection))
            {
                existsCommand.Parameters.AddWithValue("@name", databaseName);
                var result = await existsCommand.ExecuteScalarAsync();
                if (result is not DBNull && result is not null)
                {
                    throw new InvalidOperationException($"Database '{databaseName}' already exists on the server.");
                }
            }

            // CREATE DATABASE takes no parameters for identifiers. databaseName comes from
            // ResolveAvailableDatabaseNameAsync, which strips everything but letters, digits and
            // underscore, and the collation is validated against sys.fn_helpcollations below - so
            // neither value can carry tenant input into the statement text.
            await GuardCollationAsync(connection, _hrmsSettings.TemplateCollation);

            var fileClause = string.Empty;
            if (!string.IsNullOrWhiteSpace(_hrmsSettings.DataFileDirectory))
            {
                // Only when explicitly configured. Left blank, SQL Server uses its own default data
                // path - which is the right behaviour in a container or on a managed instance,
                // where this process cannot know the server's directory layout.
                var dataDir = _hrmsSettings.DataFileDirectory.TrimEnd('\\', '/');
                var separator = dataDir.Contains('/') ? "/" : "\\";
                fileClause =
                    $" ON PRIMARY (NAME = [{databaseName}], FILENAME = '{dataDir}{separator}{databaseName}.mdf')" +
                    $" LOG ON (NAME = [{databaseName}_log], FILENAME = '{dataDir}{separator}{databaseName}_log.ldf')";
            }

            var createSql = $"CREATE DATABASE [{databaseName}]{fileClause} COLLATE {_hrmsSettings.TemplateCollation}";

            using (var createCommand = new SqlCommand(createSql, connection) { CommandTimeout = 300 })
            {
                await createCommand.ExecuteNonQueryAsync();
            }

            _logger.LogInformation("Created database {DatabaseName} with collation {Collation}.",
                databaseName, _hrmsSettings.TemplateCollation);

