/// Provisioning failures must never break activation itself - the Subscription already
/// exists by this point; support can retry provisioning later. Every attempt, success or
/// failure, is recorded in TenantDatabase so nothing is silently lost.
/// </summary>
private async Task ProvisionAndNotifyAsync(Tenant tenant, PortalUser actingUser, string productCode, string productName)
{
    // Generated here, not taken from the request - the only copy anyone sees is the one in
    // the email below, which is why the email now states it explicitly.
    var productPassword = GeneratedPassword.Create();

    try
    {
        var result = await _provisioningService.ProvisionAsync(
            tenant.Id, productCode, tenant.Subdomain,
            tenant.CompanyName, actingUser.Email, actingUser.Name, actingUser.ContactNumber, productPassword);

        if (result.Success)
        {
            try
            {
                var loginUrl = _hrmsSettings.HrmsLoginUrl.StartsWith("REPLACE_") ? null : _hrmsSettings.HrmsLoginUrl;

                await _emailService.SendEmailAsync(
                    actingUser.Email,
                    $"Your {productName} workspace is ready",
                    EmailTemplates.WorkspaceReady(
                        tenant.CompanyName,
                        actingUser.Name,
                        actingUser.Email,
                        productName,
                        result.AdminLoginCode!,
                        productPassword,
                        loginUrl));
            }
            catch (Exception emailEx)
            {
                _logger.LogWarning(emailEx,
                    "Provisioning succeeded for TenantId {TenantId}, Product {ProductCode}, but the welcome email failed to send.",
                    tenant.Id, productCode);
            }
        }

