        public async Task<TenantRegistrationResult> RegisterAsync(
            string clientCode,
            string databaseName,
            string? serverName,
            CancellationToken cancellationToken = default)
        {
            if (string.IsNullOrWhiteSpace(clientCode))
            {
                throw new ArgumentException("ClientCode is required.", nameof(clientCode));
            }

            if (string.IsNullOrWhiteSpace(databaseName))
            {
                throw new ArgumentException("DatabaseName is required.", nameof(databaseName));
            }

            // The key is generated here, on the side that owns the catalogue, so the algorithm
            // (alphabet, length, hashing) lives in exactly one place. The portal receives it and
            // never has to agree with us about how one is built.
            string displayKey = ProductKey.Generate();
            string keyHash = ProductKey.Hash(ProductKey.Normalize(displayKey)!);

            const string sql = @"
                SET XACT_ABORT ON;
                BEGIN TRANSACTION;

                DECLARE @ClientID INT;
                DECLARE @Created BIT = 0;

                SELECT @ClientID = ClientID FROM dbo.HR_ClientRegistry WHERE ClientCode = @ClientCode;

                IF @ClientID IS NULL
                BEGIN
                    INSERT INTO dbo.HR_ClientRegistry (ClientCode, DatabaseName, ServerName, IsActive)
                    VALUES (@ClientCode, @DatabaseName, @ServerName, 1);
                    SET @ClientID = CAST(SCOPE_IDENTITY() AS INT);
                    SET @Created = 1;
                END
                ELSE
                BEGIN
                    -- A retried provision may point the tenant at a newly built database. IsActive
                    -- is deliberately NOT reset: if support suspended this tenant, a provisioning
                    -- retry must not quietly reinstate them.
                    UPDATE dbo.HR_ClientRegistry
                       SET DatabaseName = @DatabaseName,
                           ServerName   = @ServerName
                     WHERE ClientID = @ClientID;
                END

                INSERT INTO dbo.HR_ClientProductKey (ClientID, KeyHash, Label)
                VALUES (@ClientID, @KeyHash, @Label);

                COMMIT TRANSACTION;

                SELECT r.ClientID, r.ClientCode, r.DatabaseName, r.ServerName, r.IsActive, r.SchemaVersion, @Created AS Created
                FROM dbo.HR_ClientRegistry r WHERE r.ClientID = @ClientID;";

            try
            {
                await using var connection = new SqlConnection(RequireMasterConnectionString());
                var row = await connection.QuerySingleAsync<RegistrationRow>(new CommandDefinition(sql, new
                {
                    ClientCode = clientCode.Trim(),
                    DatabaseName = databaseName.Trim(),
                    ServerName = string.IsNullOrWhiteSpace(serverName) ? null : serverName.Trim(),
                    KeyHash = keyHash,
                    Label = "issued by subscription portal " + DateTime.UtcNow.ToString("yyyy-MM-dd")
                }, cancellationToken: cancellationToken));

                var tenant = new TenantInfo
                {
                    ClientId = row.ClientID,
                    ClientCode = row.ClientCode ?? clientCode,
                    DatabaseName = row.DatabaseName ?? databaseName,
                    ServerName = row.ServerName,
                    IsActive = row.IsActive,
                    SchemaVersion = row.SchemaVersion
                };

                // A re-registration changes the database a cached ClientID points at, so the cached
                // row must go or requests would keep resolving to the previous database until it
                // expired.
                Invalidate(tenant.ClientId);

                _logger.LogInformation(
                    "Registered tenant {ClientCode} (ClientID {ClientId}) -> {DatabaseName}. New tenant: {Created}.",
                    tenant.ClientCode, tenant.ClientId, tenant.DatabaseName, row.Created);

                return new TenantRegistrationResult(tenant, displayKey, row.Created);
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Tenant registration failed for {ClientCode}.", clientCode);
                throw new TenantResolutionException(
                    "The tenant catalogue could not be written to. Registration was not completed.");
            }
        }

        private sealed class RegistrationRow
        {
            public int ClientID { get; set; }
            public string? ClientCode { get; set; }
            public string? DatabaseName { get; set; }
            public string? ServerName { get; set; }
            public bool IsActive { get; set; }
            public int? SchemaVersion { get; set; }
            public bool Created { get; set; }
        }

