namespace SubscriptionPortal.Core.CommonModels
{
    /// <summary>
    /// How this portal tells the HRMS about a tenant it has just provisioned.
    ///
    /// Until this call succeeds the portal has a database and the HRMS has never heard of it - no
    /// catalogue row, no product key, and nobody can sign in. It is the last step of provisioning,
    /// not an optional extra.
    /// </summary>
    public class HrmsRegistrationSettings
    {
        /// <summary>Base URL of the HRMS API, no trailing slash, e.g. https://localhost:5043.</summary>
        public string BaseUrl { get; set; } = string.Empty;

        /// <summary>
        /// Must match the HRMS's MultiTenancy:PortalSharedSecret exactly. Sent as X-Portal-Secret.
        /// Interim measure - a portal service account with a real JWT is the planned replacement.
        /// </summary>
        public string SharedSecret { get; set; } = string.Empty;

        /// <summary>Seconds to wait for the HRMS. Short: provisioning already holds a request open.</summary>
        public int TimeoutSeconds { get; set; } = 30;

        public bool IsConfigured =>
            !string.IsNullOrWhiteSpace(BaseUrl) && !BaseUrl.StartsWith("REPLACE_") &&
            !string.IsNullOrWhiteSpace(SharedSecret) && !SharedSecret.StartsWith("REPLACE_");
    }
}
