using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Interface;
using SubscriptionPortal.Core.CommonModels;

namespace SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Implementation
{
    /// <summary>
    /// Calls the HRMS's /api/Tenant/Register so a freshly provisioned database becomes reachable,
    /// and brings back the product key the customer signs in with.
    ///
    /// Only identity goes over the wire - client code, database name, optionally a server. Never a
    /// connection string: the HRMS builds its own from its local template, so each application
    /// keeps its own SQL login and no credential ever crosses the network.
    /// </summary>
    public class HrmsTenantRegistrationClient : IHrmsTenantRegistrationClient
    {
        private readonly HttpClient _httpClient;
        private readonly HrmsRegistrationSettings _settings;
        private readonly ILogger<HrmsTenantRegistrationClient> _logger;

        private static readonly JsonSerializerOptions JsonOptions =
            new(JsonSerializerDefaults.Web) { PropertyNameCaseInsensitive = true };

        public HrmsTenantRegistrationClient(
            HttpClient httpClient,
            IOptions<HrmsRegistrationSettings> settings,
            ILogger<HrmsTenantRegistrationClient> logger)
        {
            _httpClient = httpClient;
            _settings = settings.Value;
            _logger = logger;
        }

        public async Task<HrmsRegistrationResult> RegisterAsync(
            string clientCode,
            string databaseName,
            string? serverName,
            CancellationToken cancellationToken = default)
        {
            if (!_settings.IsConfigured)
            {
                return new HrmsRegistrationResult(false, 0, null,
                    "HrmsRegistration is not configured (BaseUrl/SharedSecret missing in appsettings.json).");
            }

            var url = _settings.BaseUrl.TrimEnd('/') + "/api/Tenant/Register";

            using var request = new HttpRequestMessage(HttpMethod.Post, url)
            {
                Content = JsonContent.Create(new
                {
                    clientCode,
                    databaseName,
                    serverName
                })
            };

            // Per-request rather than a default header on the client, so the secret cannot leak
            // onto some other call that happens to share the HttpClient.
            request.Headers.Add("X-Portal-Secret", _settings.SharedSecret);

            try
            {
                using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                cts.CancelAfter(TimeSpan.FromSeconds(Math.Max(5, _settings.TimeoutSeconds)));

                using var response = await _httpClient.SendAsync(request, cts.Token);
                var body = await response.Content.ReadAsStringAsync(cts.Token);

                if (!response.IsSuccessStatusCode)
                {
                    // The body carries the HRMS's own ResponseModel message, which says whether the
                    // secret was rejected or the payload was. Logged, but never the secret itself.
                    var message = TryReadMessage(body) ?? $"HRMS returned {(int)response.StatusCode}.";
                    _logger.LogError(
                        "HRMS tenant registration failed for {ClientCode}: {StatusCode} {Message}",
                        clientCode, (int)response.StatusCode, message);
                    return new HrmsRegistrationResult(false, 0, null, message);
                }

                var payload = JsonSerializer.Deserialize<HrmsResponseEnvelope>(body, JsonOptions);
                var data = payload?.Data;

                if (data is null || string.IsNullOrWhiteSpace(data.ProductKey))
                {
                    _logger.LogError(
                        "HRMS tenant registration for {ClientCode} returned success with no product key.", clientCode);
                    return new HrmsRegistrationResult(false, 0, null,
                        "HRMS registered the tenant but returned no product key.");
                }

                _logger.LogInformation(
                    "Registered {ClientCode} with HRMS as ClientID {ClientId} (new tenant: {Created}).",
                    clientCode, data.ClientId, data.Created);

                return new HrmsRegistrationResult(true, data.ClientId, data.ProductKey, null);
            }
            catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                _logger.LogError("HRMS tenant registration for {ClientCode} timed out after {Seconds}s.",
                    clientCode, _settings.TimeoutSeconds);
                return new HrmsRegistrationResult(false, 0, null,
                    "The HRMS did not respond in time. The database was created but is not registered yet.");
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Could not reach the HRMS to register {ClientCode}.", clientCode);
                return new HrmsRegistrationResult(false, 0, null,
                    "The HRMS could not be reached. The database was created but is not registered yet.");
            }
        }

        private static string? TryReadMessage(string body)
        {
            try
            {
                return JsonSerializer.Deserialize<HrmsResponseEnvelope>(body, JsonOptions)?.Message;
            }
            catch (JsonException)
            {
                return null;
            }
        }

        private sealed class HrmsResponseEnvelope
        {
            public bool IsSuccess { get; set; }
            public string? Message { get; set; }
            public HrmsRegisterData? Data { get; set; }
        }

        private sealed class HrmsRegisterData
        {
            public int ClientId { get; set; }
            public string? ClientCode { get; set; }
            public string? DatabaseName { get; set; }
            public bool Created { get; set; }
            public string? ProductKey { get; set; }
        }
    }
}
