# 1. new status for "database built, HRMS not told yet"
p = 'SubscriptionPortal.Core/Enums/TenantDatabaseStatus.cs'
s = open(p).read()
old = """        Provisioning,
        Active,
        Failed,"""
new = """        Provisioning,

        /// <summary>
        /// The database exists and is fully built, but the HRMS has no catalogue entry for it yet -
        /// registration failed or the HRMS was unreachable. Nobody can sign in to this tenant.
        ///
        /// Deliberately distinct from Failed: the expensive part succeeded and must NOT be rebuilt.
        /// Recovery is to retry registration against the existing database.
        /// </summary>
        AwaitingRegistration,

        Active,
        Failed,"""
assert old in s
open(p,'w').write(s.replace(old, new, 1))

# 2. TenantDatabase stores the key (encrypted) + the HRMS client id
p = 'SubscriptionPortal.Core/Entities/TenantDatabase.cs'
s = open(p).read()
old = """        [Required]
