                var encryptedConnectionString = AesCrypto.Encrypt(tenantConnectionString, ConnectionStringEncryptionKey);
                var serverName = new SqlConnectionStringBuilder(masterConnectionString).DataSource;"""
new = """                var tenantConnectionString = BuildConnectionString(databaseName);
                await ApplyTemplateScriptsAsync(tenantConnectionString, databaseName);
                var adminCode = await SeedAdminUserAsync(tenantConnectionString, companyName, adminEmail, adminName, contactNumber, adminPassword);

                var encryptedConnectionString = AesCrypto.Encrypt(tenantConnectionString, ConnectionStringEncryptionKey);
                var serverName = new SqlConnectionStringBuilder(masterConnectionString).DataSource;

                // Tell the HRMS this tenant exists and collect the product key. Until this
                // succeeds the database is complete but unreachable - the HRMS has no catalogue
                // row for it and the sign-in screen has nothing to resolve.
                //
                // Only identity is sent. The HRMS builds its own connection from its local
                // template, so the connection string encrypted above stays here and no SQL
                // credential crosses the network.
                var clientCode = BuildClientCode(tenantSubdomain, tenantId);
                var registration = await _registrationClient.RegisterAsync(clientCode, databaseName, serverName);

                // A registration failure does NOT drop the database. The expensive, slow part
                // succeeded and the data is sound; only the catalogue entry is missing, and that is
                // retryable against the database as it stands. Dropping it would throw away a good
                // build because a remote service was briefly unreachable.
                var status = registration.Success
                    ? TenantDatabaseStatus.Active
                    : TenantDatabaseStatus.AwaitingRegistration;

