                        Status = TenantDatabaseStatus.Active,
                        ProvisionedDate = DateTime.UtcNow
                    });"""
new = """                        EncryptedConnectionString = encryptedConnectionString,
                        EncryptedProductKey = encryptedProductKey,
                        HrmsClientId = registration.ClientId,
                        Status = status,
                        FailureReason = registration.FailureReason,
                        ProvisionedDate = DateTime.UtcNow
                    });"""
assert old in s
s = s.replace(old, new, 1)

old = """                    existing.EncryptedConnectionString = encryptedConnectionString;
                    existing.Status = TenantDatabaseStatus.Active;
                    existing.ProvisionedDate = DateTime.UtcNow;
                    existing.FailureReason = null;
                    await _tenantDatabaseRepository.SaveChangesAsync();"""
new = """                    existing.EncryptedConnectionString = encryptedConnectionString;
                    existing.EncryptedProductKey = encryptedProductKey;
                    existing.HrmsClientId = registration.ClientId;
                    existing.Status = status;
                    existing.ProvisionedDate = DateTime.UtcNow;
                    existing.FailureReason = registration.FailureReason;
                    await _tenantDatabaseRepository.SaveChangesAsync();"""
