        private static string BuildClientCode(string tenantSubdomain, long tenantId) =>
            $"{SanitizeNamePart(tenantSubdomain, 40)}_T{tenantId}";

        private string BuildConnectionString(string databaseName)"""
assert old in s
s = s.replace(old, new, 1)
s = s.replace("using SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Interface;",
              "using SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Interface;", 1)
open(p,'w').write(s)
print("provisioning wired")
