      this.mode = 'tenant';
      this.tenantStep = 'key';
    }

    this.route.queryParams.subscribe(async (params) => {
      // Arriving from the subscription portal's "your workspace is ready" email, which links here
      // with the tenant's product key attached. Verify it straight away so the customer lands on
      // the password field rather than being asked for a key they were never shown.
      const linkedKey = params['productKey'];
      if (linkedKey) {
        this.mode = 'tenant';
        this.tenantStep = 'key';
