        // reason to leave it in browser history, bookmarks or a referrer header once it is in the
        // form. verifyProductKey() remembers it per browser on success anyway.
        window.history.replaceState({}, document.title, window.location.pathname);

        this.verifyProductKey();
      }

      const token = params['token'];
"""
