old = """            IReadOnlyList<TenantInfo> tenants = await _registry.GetActiveTenantsAsync(cancellationToken);"""
new = """            IReadOnlyList<TenantInfo> tenants;
            try
            {
                tenants = await _registry.GetActiveTenantsAsync(cancellationToken);
            }
            catch (Exception ex)
            {
                // Deliberately not rethrown. This runs from IHostedService.StartAsync, and the host
                // is configured with BackgroundServiceExceptionBehavior.StopHost - so letting this
                // escape means an unreachable or misconfigured catalogue stops the entire
                // application from starting, rather than degrading one piece of background work.
                //
                // The work skipped here is seeding and repair, which the existing startup runner
                // already treats as "must never block the app from serving traffic". Requests
                // themselves are unaffected: each one still resolves its own tenant and still fails
                // closed if it cannot.
                _logger.LogError(ex,
                    "Could not enumerate active tenants from the catalogue; skipping this run of per-tenant background work. " +
                    "The application will continue to start, but seeding and scheduled work has not run for any tenant.");
                return;
            }"""
assert old in s
open(p,'w').write(s.replace(old, new, 1))
print("patched")
