		public IDbTransaction? Transaction { get; private set; }

		/// <summary>
		/// Takes its connection from the request's tenant rather than reading and decrypting
		/// appsettings itself. Scoped, so this runs after TenantResolutionMiddleware has bound the
		/// tenant; on a request with no tenant, ITenantContext.ConnectionString throws instead of
		/// silently falling back to the default database.
		/// </summary>
		public DapperContext(ITenantContext tenantContext)
		{
			string connectionString = tenantContext.ConnectionString;

			// Several repositories read overlapping result sets on this single shared connection.
			if (!connectionString.Contains("MultipleActiveResultSets=True", StringComparison.OrdinalIgnoreCase))
			{
				connectionString = connectionString.TrimEnd(';') + ";MultipleActiveResultSets=True;";
			}

			Connection = new SqlConnection(connectionString);
		}"""
new = """		private readonly ITenantContext _tenantContext;
		private IDbConnection? _connection;

		/// <summary>
		/// Created on FIRST USE, not in the constructor.
		///
		/// That matters because MVC constructs every globally registered action filter before the
		/// action runs, and those filters pull repositories - and therefore this - into existence.
		/// Reading the tenant's connection in the constructor meant the connection was fixed before
		/// LoginController had a chance to resolve the product key, so a tenant sign-in would have
		/// been checked against the DEFAULT database. Resolving lazily means the connection is
		/// built after the tenant is known, whichever order the container happens to build things.
		/// </summary>
		public IDbConnection Connection => _connection ??= CreateConnection();

		public IDbTransaction? Transaction { get; private set; }

		/// <summary>
		/// Takes its connection from the request's tenant rather than reading and decrypting
		/// appsettings itself. The constructor deliberately does no work - see Connection.
		/// </summary>
		public DapperContext(ITenantContext tenantContext)
		{
			_tenantContext = tenantContext;
		}

		private IDbConnection CreateConnection()
		{
			string connectionString = _tenantContext.ConnectionString;

			// Several repositories read overlapping result sets on this single shared connection.
			if (!connectionString.Contains("MultipleActiveResultSets=True", StringComparison.OrdinalIgnoreCase))
			{
				connectionString = connectionString.TrimEnd(';') + ";MultipleActiveResultSets=True;";
			}

			return new SqlConnection(connectionString);
		}"""
assert old in s
s = s.replace(old, new, 1)

# Dispose must not create a connection just to dispose it
old_disp = """		public void Dispose()
		{
			if (Transaction != null)
			{
				Transaction.Dispose();
				Transaction = null;
			}
			if (Connection.State == ConnectionState.Open)
				Connection.Close();
			Connection?.Dispose();
		}"""
new_disp = """		public void Dispose()
		{
			if (Transaction != null)
			{
				Transaction.Dispose();
				Transaction = null;
			}

			// _connection, not Connection: on a request that never touched the database, the
			// property would otherwise BUILD a connection here purely in order to dispose it -
			// and on a request with no resolvable tenant that would throw out of Dispose.
			if (_connection is null)
			{
