# mirror the fixed logic and round-trip it
ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
def normalize(s):
    if not s or not s.strip(): return None
    cand = ''.join(c.upper() for c in s if c.isalnum())
    if len(cand) == 28 and cand.startswith("SO1"):
        cand = cand[3:]
    out = []
    for c in cand:
        c = {'I':'1','L':'1','O':'0','U':'V'}.get(c, c)
        if c not in ALPHABET: return None
        out.append(c)
    return ''.join(out) if len(out) == 25 else None

import secrets, hashlib
ok = 0
for _ in range(2000):
    payload = ''.join(ALPHABET[secrets.randbelow(32)] for _ in range(25))
    display = "SO1-" + "-".join(payload[i:i+5] for i in range(0,25,5))
    n = normalize(display)
    assert n == payload, (display, n)
    # typed variants people actually produce
    assert normalize(display.lower()) == payload
    assert normalize(display.replace("-", "")) == payload
    assert normalize(" " + display + " ") == payload
    assert normalize(payload) == payload          # prefix omitted
    ok += 1
print(f"round-trip OK for {ok} generated keys, plus lowercase / no-hyphen / whitespace / no-prefix variants")
