using System.ComponentModel.DataAnnotations;
using SubscriptionPortal.Core.Enums;

namespace SubscriptionPortal.Core.DTOs.Subscription
{
    /// <summary>
    /// Everything activation needs: which product, demo or purchase, and (for a purchase) which
    /// plan. Nothing else.
    ///
    /// <para>The company name, admin name, email and contact number are deliberately NOT accepted
    /// from the client - they are read server-side from the caller's own PortalUser/Tenant (see
    /// SubscriptionService.ActivateProductAsync). The caller is already authenticated, so asking
    /// them to re-type details the server already holds added friction and let a client submit a
    /// company name that didn't match its own account. There is no password field either: the JWT
    /// already proves who this is, and the new product's admin password is generated server-side
    /// and emailed rather than reused from the portal login.</para>
    /// </summary>
    public class ActivateProductRequest
    {
        [Required]
        [StringLength(30)]
        public string ProductCode { get; set; } = string.Empty;

        [Required]
        public SignupMode Mode { get; set; }

        /// <summary>Required when Mode is Purchase - ignored for Demo (always uses the cheapest active plan).</summary>
        public int? PlanId { get; set; }

        /// <summary>
        /// Only meaningful when subscribing to a product this company has already demoed.
        /// <para>true (the default) - keep the demo database and everything already entered in it;
        /// the existing subscription is simply converted to paid. No new database is created.</para>
        /// <para>false - start clean: a brand-new database is provisioned, and the demo one is
        /// marked Retired so it can be deleted deliberately later (its data is never destroyed
        /// automatically).</para>
        /// </summary>
        public bool ReuseExistingDatabase { get; set; } = true;
    }
}
