                var existing = await _subscriptionRepository.GetSubscriptionForProductAsync(existingTenant.Id, code);
                var live = existing is not null && existing.Status != SubscriptionStatus.Cancelled ? existing : null;

                if (isDemo)
                {
                    // One free demo per product, for good - checked against WasDemo rather than
                    // Status, so an expired or cancelled demo still counts as used.
                    if (await _subscriptionRepository.HasUsedDemoAsync(existingTenant.Id, code))
                    {
                        return ApiResponse<ActivateProductResponse>.Failure(
                            $"Your company has already used its free demo of {product.Name}. Subscribe to carry on using it.");
                    }

                    if (live is not null)
                    {
                        return ApiResponse<ActivateProductResponse>.Failure($"{product.Name} is already active for your company.");
                    }
                }
                else if (live is not null)
                {
                    // Active means paid - including a demo that has already been converted, which is
                    // why this does NOT look at WasDemo (WasDemo stays true for the life of the
                    // subscription, so testing it here would have let a paid subscription be bought
                    // a second time and re-provisioned). A demo awaiting payment is Trial, and a
                    // lapsed subscription is ReadOnly/Blocked - both can still be subscribed to.
                    if (!CanSubscribeTo(live.Status))
                    {
                        return ApiResponse<ActivateProductResponse>.Failure($"{product.Name} is already subscribed for your company.");
                    }

                    if (request.ReuseExistingDatabase)
                    {
                        // Keep the demo database and everything entered in it - the subscription is
                        // simply converted to paid. No provisioning, no second database and no new
                        // email: their existing product login keeps working exactly as before.
                        await _subscriptionRepository.ConvertToPaidAsync(live, plan.Id, live.Users);
                        return await BuildActivationResponseAsync(
                            actingUser, product, plan, live,
                            $"{product.Name} is now subscribed - you keep your existing data and login.");
                    }

                    // Start clean instead: the demo database is RETIRED (left on the server, marked
                    // safe to delete) and its subscription cancelled, then a brand-new database is
                    // provisioned below. Nothing is ever dropped automatically.
                    var retiringDatabase = await _tenantDatabaseRepository.GetByTenantAndProductAsync(existingTenant.Id, code);
                    if (retiringDatabase is not null
                        && retiringDatabase.Status != TenantDatabaseStatus.Retired
                        && retiringDatabase.Status != TenantDatabaseStatus.Deprovisioned)
                    {
                        retiringDatabase.Status = TenantDatabaseStatus.Retired;
                        await _tenantDatabaseRepository.SaveChangesAsync();
                    }

                    await _subscriptionRepository.CancelSubscriptionAsync(live);
                }

                var newSubscription = BuildSubscription(existingTenant.Id, plan.Id, isDemo);
                await _subscriptionRepository.AddSubscriptionAsync(newSubscription);
                await ProvisionAndNotifyAsync(existingTenant, actingUser, code, product.Name);

                return await BuildActivationResponseAsync(
                    actingUser, product, plan, newSubscription, $"{product.Name} has been activated.");
            }

            // ---------------------------------------------------------------- 3. First activation
            // No company yet (see PortalUser.TenantId's own doc comment) - create it now, together
            // with the subscription it is being created FOR, in a single transaction.
            if (actingUser.TenantId is not null)
            {
                return ApiResponse<ActivateProductResponse>.Failure("Could not verify the current user.");
            }

            // The company name typed at Signup, parked on the account until this moment (see
            // PortalUser.PendingCompanyName). Falls back to the person's own name only if that is
            // somehow missing, so a Tenant can never be created nameless.
            var pendingCompanyName = string.IsNullOrWhiteSpace(actingUser.PendingCompanyName)
                ? actingUser.Name
                : actingUser.PendingCompanyName.Trim();

            var tenant = new Tenant
            {
                CompanyName = pendingCompanyName,
                Subdomain = await _accountRepository.GenerateUniqueSubdomainAsync(pendingCompanyName),
                // The company's public identifier from here on - TENANT001, TENANT002, ...
                TenantCode = await _accountRepository.GenerateTenantCodeAsync(),
                Status = TenantStatus.Trial
            };

            // TenantId is filled in by the repository once the Tenant row has its identity.
            var firstSubscription = BuildSubscription(tenantId: 0, planId: plan.Id, isDemo: isDemo);
            await _accountRepository.PromotePendingUserToNewTenantAsync(actingUser, tenant, firstSubscription);

            // The product database gets its own freshly generated admin password, emailed to this
            // person - the portal login's password is only ever stored as a hash, so it cannot be
            // reused here.
            await ProvisionAndNotifyAsync(tenant, actingUser, code, product.Name);

            return await BuildActivationResponseAsync(
                actingUser, product, plan, firstSubscription, $"{product.Name} has been activated.");
        }
