using System.Security.Cryptography;
using System.Text;

namespace SubscriptionPortal.Core.Security
{
    /// <summary>Matches HRMS's AESEncryption.Encrypt/Decrypt exactly (same key-as-string,
    /// fixed zero IV approach), so the same key/ciphertext format works across both projects.</summary>
    public static class AesCrypto
    {
        public static string Encrypt(string plaintext, string password)
        {
            var key = Encoding.UTF8.GetBytes(password);
            var iv = new byte[16];

            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;

            using var memoryStream = new MemoryStream();
            using var cryptoStream = new CryptoStream(memoryStream, aes.CreateEncryptor(), CryptoStreamMode.Write);

            var inputBytes = Encoding.UTF8.GetBytes(plaintext);
