        public async Task<(ResponseModel, ListUserModel?, HashSet<string>?, List<ListAllMenu>?)> Login(string username, string password)
        {
            var response = new ResponseModel();
            ListUserModel? userModel = null;
            HashSet<string>? permissions = null;
            List<ListAllMenu>? userMenus = null;

            try
            {
                if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
                {
                    response.IsSuccess = false;
                    response.Status = HttpStatusCode.BadRequest;
                    response.Message = "Username or password not provided.";
                    return (response, null, null, null);
                }

                var user = await _loginRepository.Login(username);

                if (user == null || !PasswordMatches(user.PasswordHash, password))
                {
                    response.IsSuccess = false;
                    response.Status = HttpStatusCode.Unauthorized;
                    response.Message = "Invalid username or password.";
                    return (response, null, null, null);
                }

                // A missing/unlinked employee (EmployeeMasterId null) or an employee with no branch
                // set is not an error - HR_UserMaster no longer requires a linked, active employee
                // to log in or use any feature (matches the sibling hr_payroll project). BranchId
                // is simply null on the resulting token/session; branch-scoped features already
                // treat an absent branch as "unscoped" rather than a hard requirement.
                var branchId = await _loginRepository.GetUserBranch(user.EmployeeMasterId);

