            long userMasterId;
            using (var userCommand = new SqlCommand(
                "INSERT INTO [dbo].[HR_UserMaster] " +
                "([Code], [UserName], [Email], [PasswordHash], [Role], [CreatedBy], [CreatedDt], [SystemName], [Status], [CompanyMasterID]) " +
                "OUTPUT INSERTED.[UserMasterID] " +
                "VALUES (@code, @userName, @email, @passwordHash, 'Admin', 0, SYSUTCDATETIME(), 'SubscriptionPortal', 1, @companyMasterId)", connection))
            {
                userCommand.Parameters.AddWithValue("@code", adminCode);
                userCommand.Parameters.AddWithValue("@userName", adminName);
                userCommand.Parameters.AddWithValue("@email", adminEmail);
                userCommand.Parameters.AddWithValue("@passwordHash", encryptedPassword);
                userCommand.Parameters.AddWithValue("@companyMasterId", companyMasterId);

                userMasterId = Convert.ToInt64(await userCommand.ExecuteScalarAsync());
            }

            using (var selfCommand = new SqlCommand(
                "UPDATE [dbo].[HR_UserMaster] SET [CreatedBy] = @id WHERE [UserMasterID] = @id", connection))
            {
                selfCommand.Parameters.AddWithValue("@id", userMasterId);
                await selfCommand.ExecuteNonQueryAsync();
            }"""
