SET NOCOUNT ON;
DECLARE @t NVARCHAR(128), @c NVARCHAR(128), @sql NVARCHAR(MAX), @n INT;
DECLARE cur CURSOR FOR
  SELECT t.name, c.name
  FROM sys.tables t
  JOIN sys.columns c ON c.object_id = t.object_id
  JOIN sys.types ty ON ty.user_type_id = c.user_type_id
  WHERE c.is_nullable = 1
    AND ty.name IN ('bigint','int','smallint','tinyint','bit','datetime','datetime2','date','decimal','numeric','float')
    AND t.name IN ('HR_MenuItems','HR_MenuGroups','HR_MenuActions','HR_RolesMaster','HR_RolePermissions',
                   'HR_ApprovalStatusMaster','HR_LookupList','HR_LookupValue','HR_AppSetting','Company','HR_UserMaster');
OPEN cur;
FETCH NEXT FROM cur INTO @t, @c;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @sql = N'SELECT @n = COUNT(*) FROM dbo.' + QUOTENAME(@t) + N' WHERE ' + QUOTENAME(@c) + N' IS NULL;';
    EXEC sp_executesql @sql, N'@n INT OUTPUT', @n = @n OUTPUT;
    IF @n > 0 PRINT @t + '.' + @c + '  -> ' + CAST(@n AS varchar(10)) + ' NULL row(s)';
    FETCH NEXT FROM cur INTO @t, @c;
END
CLOSE cur; DEALLOCATE cur;
EOF
