new2 = """        /// <summary>
        /// Gives the new admin the Administrator role in HR_UserRoles.
        ///
        /// Without this they can sign in and see NOTHING. The HR_UserMaster.Role = 'Admin' string
        /// set above is the legacy field; the live permission system resolves
        /// HR_UserRoles -> HR_RolePermissions, and the menu the UI renders is derived from those
        /// permissions. No role row means no permissions, which means no menu items - a working
        /// login into an empty shell, which looks like a broken product.
        ///
        /// Matched by NAME, not by a hard-coded id: HR_RolesMaster is seeded from the template and
        /// its identity values are not guaranteed to be the same in every tenant.
        /// </summary>
        private async Task AssignAdministratorRoleAsync(SqlConnection connection, long userMasterId)
        {
            using var command = new SqlCommand(
                "DECLARE @RoleId INT; " +
                "SELECT TOP 1 @RoleId = [RoleId] FROM [dbo].[HR_RolesMaster] " +
                "  WHERE [RoleName] IN ('Administrator', 'Admin') ORDER BY [RoleId]; " +
                "IF @RoleId IS NOT NULL AND NOT EXISTS (" +
                "    SELECT 1 FROM [dbo].[HR_UserRoles] WHERE [UserId] = @userId AND [RoleId] = @RoleId) " +
                "BEGIN " +
                "  INSERT INTO [dbo].[HR_UserRoles] ([UserId], [RoleId], [AssignedBy], [AssignedDate]) " +
                "  VALUES (@userId, @RoleId, @userId, SYSUTCDATETIME()); " +
                "END " +
                "SELECT ISNULL(@RoleId, -1);", connection);

            command.Parameters.AddWithValue("@userId", userMasterId);
            var roleId = Convert.ToInt32(await command.ExecuteScalarAsync());

            if (roleId < 0)
            {
                // Not fatal - the database and login are fine - but the admin will see an empty
                // menu, so it must be visible rather than silently shrugged off.
                _logger.LogError(
                    "No Administrator role found in HR_RolesMaster for the new tenant database; " +
                    "the admin user has no permissions and will see an empty menu.");
            }
            else
            {
                _logger.LogInformation(
                    "Assigned RoleId {RoleId} (Administrator) to the new admin user {UserMasterId}.",
                    roleId, userMasterId);
            }
        }

