p = 'SubscriptionPortal.BusinessLogicLayer/Services/Subscriptions/Implementation/SubscriptionService.cs'
s = open(p).read()

# refuse activation of a coming-soon product
old = """            if (product is null)
            {
                return ApiResponse<ActivateProductResponse>.Failure($"Product '{request.ProductCode}' is not available.");
            }"""
new = """            if (product is null)
            {
                return ApiResponse<ActivateProductResponse>.Failure($"Product '{request.ProductCode}' is not available.");
            }

            // Enforced here, not just hidden in the UI. The product is deliberately VISIBLE in the
            // portal, so its code is public knowledge and this endpoint is reachable directly -
            // without this check a coming-soon product could still be demoed into existence,
            // provisioning a database for something that does not exist yet.
            if (product.IsComingSoon)
            {
                return ApiResponse<ActivateProductResponse>.Failure(
                    $"{product.Name} is coming soon and cannot be activated yet.");
            }"""
assert old in s
s = s.replace(old, new, 1)

# surface the flag on the products listing
old2 = """                ProductCode = p.Code,
                ProductName = p.Name,
                Plans = p.Plans"""
new2 = """                ProductCode = p.Code,
                ProductName = p.Name,
                IsComingSoon = p.IsComingSoon,
                Plans = p.Plans"""
assert old2 in s
s = s.replace(old2, new2, 1)
open(p,'w').write(s)
print("service patched")
