cat > SubscriptionPortal.DataAccessLayer/SqlScripts/Migration_20261024_ProductComingSoon.sql << 'EOF'
/* =============================================================================================
   Product.IsComingSoon - announce a product before it can be bought
   =============================================================================================
   Run against the SubscriptionPortal database.

   Distinct from IsActive = 0, which hides a product entirely. Coming Soon is meant to be SEEN:
   the tile is listed with a badge and no Try Demo / Subscribe buttons, and ActivateProductAsync
   refuses it, so it cannot be provisioned even by calling the API directly.

   Additive and idempotent.
   ============================================================================================= */

SET NOCOUNT ON;
GO

IF NOT EXISTS (SELECT 1 FROM sys.columns
               WHERE object_id = OBJECT_ID(N'dbo.Product') AND name = N'IsComingSoon')
BEGIN
    ALTER TABLE dbo.Product ADD IsComingSoon BIT NOT NULL
        CONSTRAINT DF_Product_IsComingSoon DEFAULT (0);
END
GO

/* Production Planning is announced but not built - provisioning currently hands it the HRMS
   template, so subscribing to it today produces an HR database under a PP name. */
UPDATE dbo.Product SET IsComingSoon = 1 WHERE Code = N'PP';
GO

SELECT Code, Name, IsActive, IsComingSoon FROM dbo.Product ORDER BY Code;
GO
EOF
