/* ---------------------------------------------------------------- coming soon */

/* Sits over the banner so the tile reads as unavailable before the eye reaches the buttons -
   someone scanning the grid should not have to look for a missing Subscribe button to work it out. */
.product-tile__ribbon {
    position: absolute;
    top: 12px;
    right: 12px;
    z-index: 2;
    padding: 4px 12px;
    border-radius: 999px;
    background: rgba(17, 24, 39, .82);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .04em;
