cat > /home/rudy/docs/office/subscription_portal/BE/SubscriptionPortal.DataAccessLayer/SqlScripts/Reset_CustomerData.sql << 'EOF'
/* =============================================================================================
   DESTRUCTIVE - clears all customer data from the Subscription Portal
   =============================================================================================
   Run against the SubscriptionPortal database.

   Deletes every tenant, subscription, payment, tenant-database row and non-owner portal user.

   KEPT on purpose:
     - platform owner logins (IsPlatformOwner = 1), detached from their tenant. Deleting these
       leaves no way into the portal at all: signup creates an ordinary user, not an owner, so the
       admin screens would be unreachable until a row was added by hand.
     - Product, SubscriptionPlan, RoleMaster, PageMaster - configuration, not customer data.

   This does NOT touch SQL Server itself. Tenant databases and the HR_Master catalogue are
   separate; see the companion commands at the bottom.
   ============================================================================================= */

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF OBJECT_ID(N'dbo.Tenant') IS NULL
BEGIN
    RAISERROR(N'dbo.Tenant does not exist here. Run this against the SubscriptionPortal database.', 16, 1);
    SET NOEXEC ON;
END
GO

BEGIN TRANSACTION;

/* Detach the owners FIRST - they are kept, but their Tenant is about to be deleted and the FK
   would otherwise block it. */
UPDATE dbo.PortalUser
   SET TenantId = NULL, PendingCompanyName = NULL
 WHERE IsPlatformOwner = 1;

/* Child-to-parent, so no foreign key is ever left dangling mid-delete. */
DELETE FROM dbo.Payment;
DELETE FROM dbo.Subscription;
DELETE FROM dbo.TenantDatabase;
DELETE FROM dbo.PortalUser WHERE IsPlatformOwner = 0;
DELETE FROM dbo.Tenant;

COMMIT TRANSACTION;
GO

/* Reseed so the next customer is T1 again and database names start clean. RESEED to 0 makes the
   next identity 1; for PortalUser it is set to the highest surviving id instead, so the owner's
   own row is never reused. */
DECLARE @MaxUser BIGINT = ISNULL((SELECT MAX(Id) FROM dbo.PortalUser), 0);
DBCC CHECKIDENT ('dbo.PortalUser',     RESEED, @MaxUser) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.Tenant',         RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.Subscription',   RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.TenantDatabase', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.Payment',        RESEED, 0) WITH NO_INFOMSGS;
GO

SET NOEXEC OFF;
GO

SELECT 'PortalUser (kept)' AS TableName, COUNT(*) AS Rows FROM dbo.PortalUser
UNION ALL SELECT 'Tenant',           COUNT(*) FROM dbo.Tenant
UNION ALL SELECT 'Subscription',     COUNT(*) FROM dbo.Subscription
UNION ALL SELECT 'TenantDatabase',   COUNT(*) FROM dbo.TenantDatabase
UNION ALL SELECT 'Payment',          COUNT(*) FROM dbo.Payment
UNION ALL SELECT 'Product (config)', COUNT(*) FROM dbo.Product
UNION ALL SELECT 'SubscriptionPlan', COUNT(*) FROM dbo.SubscriptionPlan;
GO

/* ---------------------------------------------------------------------------------------------
   SQL Server side, run separately and deliberately - these DROP databases.

     USE HR_Master;
     DELETE FROM dbo.HR_ClientProductKey;
     DELETE FROM dbo.HR_ClientRegistry;
     DBCC CHECKIDENT ('dbo.HR_ClientRegistry', RESEED, 0);

     -- one per provisioned tenant
     ALTER DATABASE [HR_xxx_T1] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
     DROP DATABASE [HR_xxx_T1];
   --------------------------------------------------------------------------------------------- */
EOF
